"""Curated catalog of materially distinct Python task specifications."""

TASK_CODE_SPECS = (
    ('normalized_string_counts', 'Write a Python function that strips and lowercases each string, ignores empty results, returns occurrence counts, and does not mutate the input.', 'def count_normalized_strings(values):\n    counts = {}\n    for value in values:\n        cleaned = value.strip().lower()\n        if cleaned:\n            counts[cleaned] = counts.get(cleaned, 0) + 1\n    return counts'),
    ('filter_sort_projection', 'Write a Python function that keeps records meeting a minimum score, sorts the retained records by descending score, returns their labels, and does not mutate the input.', 'def select_ranked_labels(records, minimum):\n    kept = [row for row in records if row["score"] >= minimum]\n    ordered = sorted(kept, key=lambda row: row["score"], reverse=True)\n    return [row["label"] for row in ordered]'),
    ('grouped_numeric_totals', "Write a Python function that sums each record's amount by category, returns a new category-to-total dictionary, and does not mutate the records.", 'def totals_by_category(records):\n    totals = {}\n    for row in records:\n        category = row["category"]\n        totals[category] = totals.get(category, 0) + row["amount"]\n    return totals'),
    ('grouped_numeric_averages', 'Write a Python function that computes the arithmetic mean of record values for each group, returns a new dictionary, and does not mutate the records.', 'def averages_by_group(records):\n    totals = {}\n    counts = {}\n    for row in records:\n        group = row["group"]\n        totals[group] = totals.get(group, 0) + row["value"]\n        counts[group] = counts.get(group, 0) + 1\n    return {group: totals[group] / counts[group] for group in totals}'),
    ('paired_margin_classification', 'Write a Python function that compares paired numbers from two equal-length sequences, classifies each pair as left ahead, right ahead, or within a supplied margin, returns the three counts, and does not mutate either sequence.', 'def classify_pair_margins(left_values, right_values, margin):\n    counts = {"left_ahead": 0, "right_ahead": 0, "within_margin": 0}\n    for left, right in zip(left_values, right_values):\n        if left - right > margin:\n            counts["left_ahead"] += 1\n        elif right - left > margin:\n            counts["right_ahead"] += 1\n        else:\n            counts["within_margin"] += 1\n    return counts'),
    ('nested_filter_transform', 'Write a Python function that processes every row in a nested integer list, keeps nonnegative values, doubles each retained value, preserves row boundaries and order, and does not mutate the input.', 'def double_nonnegative_rows(rows):\n    return [[value * 2 for value in row if value >= 0] for row in rows]'),
    ('select_by_nested_total', 'Write a Python function that returns the names of records whose list of values has a sum above a supplied threshold, preserves input order, and does not mutate the records.', 'def names_above_value_total(records, threshold):\n    return [row["name"] for row in records if sum(row["values"]) > threshold]'),
    ('dictionary_keywise_sum', 'Write a Python function that adds values from two dictionaries over their union of keys, treats missing values as zero, returns a new dictionary, and does not mutate either input.', 'def add_dictionary_values(first, second):\n    result = {}\n    for key in set(first) | set(second):\n        result[key] = first.get(key, 0) + second.get(key, 0)\n    return result'),
    ('stable_unique_values', 'Write a Python function that removes duplicate hashable values while preserving first-occurrence order, returns a new list, and does not mutate the input.', 'def unique_in_order(values):\n    seen = set()\n    result = []\n    for value in values:\n        if value not in seen:\n            seen.add(value)\n            result.append(value)\n    return result'),
    ('running_totals', 'Write a Python function that returns the cumulative sum after each number in a sequence and does not mutate the input.', 'def cumulative_sums(values):\n    result = []\n    total = 0\n    for value in values:\n        total += value\n        result.append(total)\n    return result'),
    ('fixed_size_chunks', 'Write a Python function that divides a sequence into consecutive lists of a positive maximum size, includes a shorter final chunk when needed, and does not mutate the input.', 'def chunk_values(values, size):\n    if size <= 0:\n        raise ValueError("size must be positive")\n    return [list(values[index:index + size]) for index in range(0, len(values), size)]'),
    ('group_records_by_key', 'Write a Python function that groups records by their category field, preserves record order within each group, returns copied records in new lists, and does not mutate the input.', 'def group_records_by_category(records):\n    grouped = {}\n    for row in records:\n        grouped.setdefault(row["category"], []).append(row.copy())\n    return grouped'),
    ('merge_sorted_sequences', 'Write a Python function that merges two ascending numeric sequences into one ascending list in linear time and does not mutate either input.', 'def merge_sorted_values(first, second):\n    merged = []\n    left = right = 0\n    while left < len(first) and right < len(second):\n        if first[left] <= second[right]:\n            merged.append(first[left])\n            left += 1\n        else:\n            merged.append(second[right])\n            right += 1\n    merged.extend(first[left:])\n    merged.extend(second[right:])\n    return merged'),
    ('sliding_window_sums', 'Write a Python function that returns the sum of every consecutive window of a positive size, returns an empty list when the window exceeds the sequence, and does not mutate the input.', 'def sliding_sums(values, width):\n    if width <= 0:\n        raise ValueError("width must be positive")\n    if width > len(values):\n        return []\n    total = sum(values[:width])\n    result = [total]\n    for index in range(width, len(values)):\n        total += values[index] - values[index - width]\n        result.append(total)\n    return result'),
    ('maximum_record_per_group', 'Write a Python function that selects the highest-scoring record in each group, keeps the first record on ties, returns copied records in a new dictionary, and does not mutate the input.', 'def best_record_by_group(records):\n    best = {}\n    for row in records:\n        group = row["group"]\n        if group not in best or row["score"] > best[group]["score"]:\n            best[group] = row.copy()\n    return best'),
    ('matrix_transpose', 'Write a Python function that transposes a rectangular nested list, rejects rows of unequal length, returns new lists, and does not mutate the matrix.', 'def transpose_rectangular(matrix):\n    if not matrix:\n        return []\n    width = len(matrix[0])\n    if any(len(row) != width for row in matrix):\n        raise ValueError("matrix must be rectangular")\n    return [[row[column] for row in matrix] for column in range(width)]'),
    ('predicate_partition', 'Write a Python function that partitions values into matching and nonmatching lists using a supplied predicate, preserves order, returns both lists, and does not mutate the input.', 'def partition_values(values, predicate):\n    matching = []\n    remaining = []\n    for value in values:\n        if predicate(value):\n            matching.append(value)\n        else:\n            remaining.append(value)\n    return matching, remaining'),
    ('unique_record_index', 'Write a Python function that indexes copied records by their id field, raises an error for a repeated id, returns a new dictionary, and does not mutate the records.', 'def index_records_by_id(records):\n    indexed = {}\n    for row in records:\n        identifier = row["id"]\n        if identifier in indexed:\n            raise ValueError("duplicate id")\n        indexed[identifier] = row.copy()\n    return indexed'),
    ('grouped_numeric_ranges', 'Write a Python function that returns the minimum and maximum value observed for each group and does not mutate the records.', 'def value_ranges_by_group(records):\n    ranges = {}\n    for row in records:\n        group = row["group"]\n        value = row["value"]\n        if group not in ranges:\n            ranges[group] = [value, value]\n        else:\n            ranges[group][0] = min(ranges[group][0], value)\n            ranges[group][1] = max(ranges[group][1], value)\n    return {group: tuple(bounds) for group, bounds in ranges.items()}'),
    ('balance_event_series', 'Write a Python function that applies signed transaction amounts to an opening balance, returns the balance after every transaction, and does not mutate the transactions.', 'def balances_after_transactions(opening, transactions):\n    balances = []\n    current = opening\n    for transaction in transactions:\n        current += transaction["amount"]\n        balances.append(current)\n    return balances'),
    ('stable_frequency_mode', 'Write a Python function that returns the most frequent hashable value, resolves ties by first occurrence, returns None for empty input, and does not mutate the sequence.', 'def first_mode(values):\n    if not values:\n        return None\n    counts = {}\n    first_positions = {}\n    for index, value in enumerate(values):\n        counts[value] = counts.get(value, 0) + 1\n        first_positions.setdefault(value, index)\n    return min(counts, key=lambda value: (-counts[value], first_positions[value]))'),
    ('adjacent_differences', 'Write a Python function that returns each value minus its immediate predecessor, returns an empty list for fewer than two values, and does not mutate the input.', 'def adjacent_differences(values):\n    return [values[index] - values[index - 1] for index in range(1, len(values))]'),
    ('nested_mapping_lookup', 'Write a Python function that follows a sequence of keys through nested dictionaries, returns a supplied default when a key is absent or an intermediate value is not a dictionary, and does not mutate the mapping.', 'def nested_lookup(mapping, keys, default=None):\n    current = mapping\n    for key in keys:\n        if not isinstance(current, dict) or key not in current:\n            return default\n        current = current[key]\n    return current'),
    ('sparse_vector_dot_product', 'Write a Python function that computes the dot product of two sparse vectors represented as dictionaries and does not mutate either dictionary.', 'def sparse_dot_product(first, second):\n    if len(first) > len(second):\n        first, second = second, first\n    return sum(value * second.get(key, 0) for key, value in first.items())'),
    ('binary_search', 'Write a Python function that returns the first index of a target in an ascending sequence, or -1 when absent, using binary search without mutating the sequence.', 'def first_binary_search(values, target):\n    left, right = 0, len(values)\n    while left < right:\n        middle = (left + right) // 2\n        if values[middle] < target:\n            left = middle + 1\n        else:\n            right = middle\n    return left if left < len(values) and values[left] == target else -1'),
    ('merge_intervals', 'Write a Python function that merges overlapping closed intervals, returns sorted new lists, accepts intervals in any order, and does not mutate the input.', 'def merge_closed_intervals(intervals):\n    ordered = sorted((start, end) for start, end in intervals)\n    merged = []\n    for start, end in ordered:\n        if not merged or start > merged[-1][1]:\n            merged.append([start, end])\n        else:\n            merged[-1][1] = max(merged[-1][1], end)\n    return merged'),
    ('interval_intersections', 'Write a Python function that returns all intersections between two lists of disjoint closed intervals already sorted by start, using a two-pointer scan and without mutating either input.', 'def intersect_interval_lists(first, second):\n    result = []\n    left = right = 0\n    while left < len(first) and right < len(second):\n        start = max(first[left][0], second[right][0])\n        end = min(first[left][1], second[right][1])\n        if start <= end:\n            result.append([start, end])\n        if first[left][1] < second[right][1]:\n            left += 1\n        else:\n            right += 1\n    return result'),
    ('maximum_nonoverlapping_intervals', 'Write a Python function that selects the maximum number of mutually nonoverlapping half-open intervals, returns selected intervals ordered by finishing time, and does not mutate the input.', 'def select_nonoverlapping(intervals):\n    selected = []\n    last_end = None\n    for start, end in sorted(intervals, key=lambda item: (item[1], item[0])):\n        if last_end is None or start >= last_end:\n            selected.append((start, end))\n            last_end = end\n    return selected'),
    ('breadth_first_distances', 'Write a Python function that computes unweighted shortest-path distances from a start node in a graph represented by an adjacency dictionary, ignores unreachable nodes, and does not mutate the graph.', 'def breadth_first_distances(graph, start):\n    distances = {start: 0}\n    queue = [start]\n    position = 0\n    while position < len(queue):\n        node = queue[position]\n        position += 1\n        for neighbor in graph.get(node, []):\n            if neighbor not in distances:\n                distances[neighbor] = distances[node] + 1\n                queue.append(neighbor)\n    return distances'),
    ('topological_sort', 'Write a Python function that topologically orders every node in a directed adjacency dictionary, includes nodes appearing only as neighbors, and raises ValueError when a cycle exists.', 'def topological_order(graph):\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    indegree = {node: 0 for node in nodes}\n    for neighbors in graph.values():\n        for neighbor in neighbors:\n            indegree[neighbor] += 1\n    ready = [node for node in nodes if indegree[node] == 0]\n    result = []\n    while ready:\n        node = ready.pop()\n        result.append(node)\n        for neighbor in graph.get(node, []):\n            indegree[neighbor] -= 1\n            if indegree[neighbor] == 0:\n                ready.append(neighbor)\n    if len(result) != len(nodes):\n        raise ValueError("graph contains a cycle")\n    return result'),
    ('connected_components', 'Write a Python function that returns the connected components of an undirected adjacency dictionary as sets, including neighbor-only nodes, without mutating the graph.', 'def connected_components(graph):\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    remaining = set(nodes)\n    components = []\n    while remaining:\n        start = remaining.pop()\n        component = {start}\n        stack = [start]\n        while stack:\n            node = stack.pop()\n            for neighbor in graph.get(node, []):\n                if neighbor in remaining:\n                    remaining.remove(neighbor)\n                    component.add(neighbor)\n                    stack.append(neighbor)\n        components.append(component)\n    return components'),
    ('dijkstra_distances', 'Write a Python function that computes shortest distances from a start node in a nonnegative weighted adjacency dictionary using a heap supplied through ordinary list operations, without mutating the graph.', 'def shortest_weighted_distances(graph, start):\n    distances = {start: 0}\n    pending = [(0, start)]\n    while pending:\n        pending.sort(reverse=True)\n        distance, node = pending.pop()\n        if distance != distances.get(node):\n            continue\n        for neighbor, weight in graph.get(node, []):\n            candidate = distance + weight\n            if candidate < distances.get(neighbor, float("inf")):\n                distances[neighbor] = candidate\n                pending.append((candidate, neighbor))\n    return distances'),
    ('balanced_delimiters', 'Write a Python function that checks whether parentheses, brackets, and braces in a string are correctly nested while ignoring all other characters.', 'def delimiters_are_balanced(text):\n    opening = {")": "(", "]": "[", "}": "{"}\n    stack = []\n    for character in text:\n        if character in opening.values():\n            stack.append(character)\n        elif character in opening:\n            if not stack or stack.pop() != opening[character]:\n                return False\n    return not stack'),
    ('run_length_encode', 'Write a Python function that run-length encodes a string as a list of character-count tuples, returns an empty list for empty input, and preserves character case.', 'def run_length_encode(text):\n    if not text:\n        return []\n    encoded = []\n    current = text[0]\n    count = 1\n    for character in text[1:]:\n        if character == current:\n            count += 1\n        else:\n            encoded.append((current, count))\n            current, count = character, 1\n    encoded.append((current, count))\n    return encoded'),
    ('longest_common_prefix', 'Write a Python function that returns the longest common prefix of a sequence of strings, returns an empty string for empty input, and does not mutate the strings.', 'def longest_common_prefix(values):\n    if not values:\n        return ""\n    prefix = values[0]\n    for value in values[1:]:\n        limit = min(len(prefix), len(value))\n        index = 0\n        while index < limit and prefix[index] == value[index]:\n            index += 1\n        prefix = prefix[:index]\n        if not prefix:\n            break\n    return prefix'),
    ('group_anagrams', 'Write a Python function that groups strings that are anagrams, preserves first-group and within-group input order, treats case as significant, and does not mutate the input.', 'def group_anagrams(values):\n    groups = {}\n    order = []\n    for value in values:\n        key = tuple(sorted(value))\n        if key not in groups:\n            groups[key] = []\n            order.append(key)\n        groups[key].append(value)\n    return [groups[key] for key in order]'),
    ('edit_distance', 'Write a Python function that computes the Levenshtein edit distance between two strings using dynamic programming with one row of storage.', 'def edit_distance(first, second):\n    previous = list(range(len(second) + 1))\n    for left_index, left_character in enumerate(first, 1):\n        current = [left_index]\n        for right_index, right_character in enumerate(second, 1):\n            current.append(min(current[-1] + 1, previous[right_index] + 1, previous[right_index - 1] + (left_character != right_character)))\n        previous = current\n    return previous[-1]'),
    ('spiral_matrix', 'Write a Python function that returns elements of a rectangular matrix in clockwise spiral order, returns an empty list for an empty matrix, and does not mutate the matrix.', 'def spiral_values(matrix):\n    if not matrix:\n        return []\n    top, bottom = 0, len(matrix) - 1\n    left, right = 0, len(matrix[0]) - 1\n    result = []\n    while top <= bottom and left <= right:\n        result.extend(matrix[top][left:right + 1])\n        top += 1\n        for row in range(top, bottom + 1):\n            result.append(matrix[row][right])\n        right -= 1\n        if top <= bottom:\n            result.extend(reversed(matrix[bottom][left:right + 1]))\n            bottom -= 1\n        if left <= right:\n            for row in range(bottom, top - 1, -1):\n                result.append(matrix[row][left])\n            left += 1\n    return result'),
    ('prefix_range_sums', 'Write a Python function that answers inclusive range-sum queries over a numeric sequence using one prefix-sum table and does not mutate the inputs.', 'def range_sum_queries(values, queries):\n    prefix = [0]\n    for value in values:\n        prefix.append(prefix[-1] + value)\n    result = []\n    for start, end in queries:\n        if start < 0 or end < start or end >= len(values):\n            raise ValueError("invalid range")\n        result.append(prefix[end + 1] - prefix[start])\n    return result'),
    ('maximum_subarray', 'Write a Python function that returns the maximum sum of a non-empty contiguous subarray using a linear scan and does not mutate the sequence.', 'def maximum_subarray_sum(values):\n    if not values:\n        raise ValueError("values must be non-empty")\n    best = current = values[0]\n    for value in values[1:]:\n        current = max(value, current + value)\n        best = max(best, current)\n    return best'),
    ('two_sum_indices', 'Write a Python function that returns the first pair of indices encountered whose values sum to a target, returns None when no pair exists, and does not mutate the sequence.', 'def first_two_sum_indices(values, target):\n    seen = {}\n    for index, value in enumerate(values):\n        complement = target - value\n        if complement in seen:\n            return seen[complement], index\n        seen.setdefault(value, index)\n    return None'),
    ('longest_unique_substring', 'Write a Python function that returns the length of the longest substring containing no repeated characters using a sliding window.', 'def longest_unique_substring_length(text):\n    last_seen = {}\n    start = 0\n    best = 0\n    for index, character in enumerate(text):\n        if character in last_seen and last_seen[character] >= start:\n            start = last_seen[character] + 1\n        last_seen[character] = index\n        best = max(best, index - start + 1)\n    return best'),
    ('histogram_largest_rectangle', 'Write a Python function that returns the largest rectangular area under a nonnegative histogram using a monotonic stack and does not mutate the heights.', 'def largest_histogram_rectangle(heights):\n    stack = []\n    best = 0\n    for index, height in enumerate(list(heights) + [0]):\n        start = index\n        while stack and stack[-1][1] > height:\n            position, previous = stack.pop()\n            best = max(best, previous * (index - position))\n            start = position\n        stack.append((start, height))\n    return best'),
    ('flatten_nested_mapping', 'Write a Python function that flattens nested dictionaries into dot-separated key paths, treats non-dictionary values as leaves, and does not mutate the mapping.', 'def flatten_mapping(mapping):\n    result = {}\n    stack = [("", mapping)]\n    while stack:\n        prefix, value = stack.pop()\n        if isinstance(value, dict):\n            for key, child in value.items():\n                path = str(key) if not prefix else prefix + "." + str(key)\n                stack.append((path, child))\n        else:\n            result[prefix] = value\n    return result'),
    ('mapping_changes', 'Write a Python function that compares two dictionaries and returns separate dictionaries for added, removed, and changed keys without mutating either input.', 'def mapping_changes(before, after):\n    added = {key: after[key] for key in after.keys() - before.keys()}\n    removed = {key: before[key] for key in before.keys() - after.keys()}\n    changed = {key: (before[key], after[key]) for key in before.keys() & after.keys() if before[key] != after[key]}\n    return {"added": added, "removed": removed, "changed": changed}'),
    ('relational_inner_join', 'Write a Python function that performs an inner join between two record lists on configurable key fields, merges matching records into new dictionaries, and preserves left-then-right match order.', 'def inner_join_records(left_rows, right_rows, left_key, right_key):\n    index = {}\n    for row in right_rows:\n        index.setdefault(row[right_key], []).append(row)\n    result = []\n    for left in left_rows:\n        for right in index.get(left[left_key], []):\n            merged = left.copy()\n            merged.update(right)\n            result.append(merged)\n    return result'),
    ('dependency_closure', 'Write a Python function that returns every transitive dependency reachable from a requested item in a dependency dictionary, excludes the item itself, and handles cycles.', 'def transitive_dependencies(graph, item):\n    found = set()\n    stack = list(graph.get(item, []))\n    while stack:\n        dependency = stack.pop()\n        if dependency == item or dependency in found:\n            continue\n        found.add(dependency)\n        stack.extend(graph.get(dependency, []))\n    return found'),
    ('top_k_frequencies', 'Write a Python function that returns the k most frequent hashable values ordered by descending frequency and then first occurrence, without mutating the input.', 'def top_k_frequent(values, k):\n    counts = {}\n    first = {}\n    for index, value in enumerate(values):\n        counts[value] = counts.get(value, 0) + 1\n        first.setdefault(value, index)\n    ordered = sorted(counts, key=lambda value: (-counts[value], first[value]))\n    return ordered[:max(0, k)]'),
    ('count_grid_regions', 'Write a Python function that counts four-directionally connected regions of truthy cells in a rectangular grid without mutating the grid.', 'def count_grid_regions(grid):\n    if not grid:\n        return 0\n    seen = set()\n    regions = 0\n    for row in range(len(grid)):\n        for column in range(len(grid[0])):\n            if not grid[row][column] or (row, column) in seen:\n                continue\n            regions += 1\n            seen.add((row, column))\n            stack = [(row, column)]\n            while stack:\n                current_row, current_column = stack.pop()\n                for next_row, next_column in ((current_row - 1, current_column), (current_row + 1, current_column), (current_row, current_column - 1), (current_row, current_column + 1)):\n                    if 0 <= next_row < len(grid) and 0 <= next_column < len(grid[0]) and grid[next_row][next_column] and (next_row, next_column) not in seen:\n                        seen.add((next_row, next_column))\n                        stack.append((next_row, next_column))\n    return regions'),
    ('shortest_grid_path', 'Write a Python function that returns the minimum number of four-directional moves between two open cells in a rectangular zero-one grid, where zero is open, or None when unreachable.', 'def shortest_grid_path(grid, start, goal):\n    if start == goal:\n        return 0\n    distances = {start: 0}\n    queue = [start]\n    position = 0\n    while position < len(queue):\n        row, column = queue[position]\n        position += 1\n        for neighbor in ((row - 1, column), (row + 1, column), (row, column - 1), (row, column + 1)):\n            next_row, next_column = neighbor\n            if 0 <= next_row < len(grid) and 0 <= next_column < len(grid[0]) and grid[next_row][next_column] == 0 and neighbor not in distances:\n                distances[neighbor] = distances[(row, column)] + 1\n                if neighbor == goal:\n                    return distances[neighbor]\n                queue.append(neighbor)\n    return None'),
    ('matrix_multiplication', 'Write a Python function that multiplies two compatible rectangular numeric matrices, rejects incompatible dimensions, returns a new matrix, and does not mutate either input.', 'def multiply_matrices(left, right):\n    if not left or not right or not right[0] or len(left[0]) != len(right):\n        raise ValueError("incompatible matrices")\n    if any(len(row) != len(left[0]) for row in left) or any(len(row) != len(right[0]) for row in right):\n        raise ValueError("matrices must be rectangular")\n    return [[sum(left[row][inner] * right[inner][column] for inner in range(len(right))) for column in range(len(right[0]))] for row in range(len(left))]'),
    ('rotate_square_matrix', 'Write a Python function that returns a new square matrix rotated 90 degrees clockwise, rejects non-square input, and does not mutate the matrix.', 'def rotate_square_clockwise(matrix):\n    size = len(matrix)\n    if any(len(row) != size for row in matrix):\n        raise ValueError("matrix must be square")\n    return [[matrix[size - 1 - row][column] for row in range(size)] for column in range(size)]'),
    ('sieve_primes', 'Write a Python function that returns every prime number less than or equal to a nonnegative integer using the sieve of Eratosthenes.', 'def primes_through(limit):\n    if limit < 2:\n        return []\n    prime = [True] * (limit + 1)\n    prime[0] = prime[1] = False\n    candidate = 2\n    while candidate * candidate <= limit:\n        if prime[candidate]:\n            for multiple in range(candidate * candidate, limit + 1, candidate):\n                prime[multiple] = False\n        candidate += 1\n    return [value for value, is_prime in enumerate(prime) if is_prime]'),
    ('prime_factorization', 'Write a Python function that returns the prime factorization of an integer greater than one as a list of factors in ascending order.', 'def prime_factors(value):\n    if value <= 1:\n        raise ValueError("value must exceed one")\n    factors = []\n    divisor = 2\n    while divisor * divisor <= value:\n        while value % divisor == 0:\n            factors.append(divisor)\n            value //= divisor\n        divisor += 1\n    if value > 1:\n        factors.append(value)\n    return factors'),
    ('polynomial_evaluation', "Write a Python function that evaluates coefficients ordered from highest to lowest degree at a supplied value using Horner's method without mutating the coefficients.", 'def evaluate_polynomial(coefficients, value):\n    result = 0\n    for coefficient in coefficients:\n        result = result * value + coefficient\n    return result'),
    ('longest_increasing_subsequence', 'Write a Python function that returns the length of the longest strictly increasing subsequence in a numeric sequence using binary-search tails and without mutating the input.', 'def increasing_subsequence_length(values):\n    tails = []\n    for value in values:\n        left, right = 0, len(tails)\n        while left < right:\n            middle = (left + right) // 2\n            if tails[middle] < value:\n                left = middle + 1\n            else:\n                right = middle\n        if left == len(tails):\n            tails.append(value)\n        else:\n            tails[left] = value\n    return len(tails)'),
    ('longest_common_subsequence', 'Write a Python function that returns the length of the longest common subsequence of two strings using dynamic programming and one row of storage.', 'def common_subsequence_length(first, second):\n    previous = [0] * (len(second) + 1)\n    for left_character in first:\n        current = [0]\n        for index, right_character in enumerate(second, 1):\n            if left_character == right_character:\n                current.append(previous[index - 1] + 1)\n            else:\n                current.append(max(previous[index], current[-1]))\n        previous = current\n    return previous[-1]'),
    ('minimum_coin_count', 'Write a Python function that returns the minimum number of positive-denomination coins needed to make an exact nonnegative amount, or None when impossible.', 'def minimum_coins(denominations, amount):\n    best = [0] + [None] * amount\n    for subtotal in range(1, amount + 1):\n        candidates = [best[subtotal - coin] + 1 for coin in denominations if 0 < coin <= subtotal and best[subtotal - coin] is not None]\n        if candidates:\n            best[subtotal] = min(candidates)\n    return best[amount]'),
    ('zero_one_knapsack', 'Write a Python function that returns the maximum value obtainable within a nonnegative capacity from paired positive weights and values, using each item at most once.', 'def maximum_knapsack_value(weights, values, capacity):\n    if len(weights) != len(values):\n        raise ValueError("weights and values must align")\n    best = [0] * (capacity + 1)\n    for weight, value in zip(weights, values):\n        if weight <= 0:\n            raise ValueError("weights must be positive")\n        for remaining in range(capacity, weight - 1, -1):\n            best[remaining] = max(best[remaining], best[remaining - weight] + value)\n    return best[capacity]'),
    ('subset_sum', 'Write a Python function that reports whether some subset of nonnegative integers sums exactly to a nonnegative target without mutating the input.', 'def has_subset_sum(values, target):\n    reachable = {0}\n    for value in values:\n        if value < 0:\n            raise ValueError("values must be nonnegative")\n        reachable.update(subtotal + value for subtotal in tuple(reachable) if subtotal + value <= target)\n    return target in reachable'),
    ('cartesian_product', 'Write a Python function that returns the Cartesian product of a sequence of input sequences as tuples, including one empty tuple for no input sequences.', 'def cartesian_product(sequences):\n    result = [()]\n    for sequence in sequences:\n        result = [prefix + (value,) for prefix in result for value in sequence]\n    return result'),
    ('power_set', 'Write a Python function that returns every subset of a sequence as tuples in iterative construction order without mutating the input.', 'def power_set(values):\n    subsets = [()]\n    for value in values:\n        subsets.extend(subset + (value,) for subset in tuple(subsets))\n    return subsets'),
    ('unique_permutations', 'Write a Python function that returns all distinct permutations of a possibly repeated sequence as tuples without mutating the input.', 'def unique_permutations(values):\n    counts = {}\n    for value in values:\n        counts[value] = counts.get(value, 0) + 1\n    result = []\n    current = []\n    def build():\n        if len(current) == len(values):\n            result.append(tuple(current))\n            return\n        for value in counts:\n            if counts[value]:\n                counts[value] -= 1\n                current.append(value)\n                build()\n                current.pop()\n                counts[value] += 1\n    build()\n    return result'),
    ('roman_numeral_parse', 'Write a Python function that converts a valid uppercase Roman numeral to an integer by accounting for subtractive pairs.', 'def roman_to_integer(text):\n    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}\n    total = 0\n    previous = 0\n    for character in reversed(text):\n        value = values[character]\n        if value < previous:\n            total -= value\n        else:\n            total += value\n            previous = value\n    return total'),
    ('integer_base_conversion', 'Write a Python function that converts a nonnegative integer to a string in base 2 through 36 using uppercase digits and without library conversion helpers.', 'def integer_to_base(value, base):\n    if value < 0 or not 2 <= base <= 36:\n        raise ValueError("invalid value or base")\n    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"\n    if value == 0:\n        return "0"\n    result = []\n    while value:\n        value, remainder = divmod(value, base)\n        result.append(digits[remainder])\n    return "".join(reversed(result))'),
    ('quoted_field_split', 'Write a Python function that splits a line on a one-character delimiter while preserving delimiters inside double-quoted fields and removing the surrounding quotes.', 'def split_quoted_fields(line, delimiter=","):\n    fields = []\n    current = []\n    quoted = False\n    for character in line:\n        if character == \'"\':\n            quoted = not quoted\n        elif character == delimiter and not quoted:\n            fields.append("".join(current))\n            current = []\n        else:\n            current.append(character)\n    if quoted:\n        raise ValueError("unclosed quote")\n    fields.append("".join(current))\n    return fields'),
    ('word_wrap', 'Write a Python function that greedily wraps whitespace-separated words into lines no longer than a positive width and raises an error when a single word exceeds the width.', 'def wrap_words(text, width):\n    if width <= 0:\n        raise ValueError("width must be positive")\n    lines = []\n    current = []\n    length = 0\n    for word in text.split():\n        if len(word) > width:\n            raise ValueError("word exceeds width")\n        required = len(word) if not current else len(word) + 1\n        if length + required > width:\n            lines.append(" ".join(current))\n            current = [word]\n            length = len(word)\n        else:\n            current.append(word)\n            length += required\n    if current:\n        lines.append(" ".join(current))\n    return lines'),
    ('weighted_group_average', 'Write a Python function that computes a weighted average for each group from records containing group, value, and nonnegative weight fields, omitting groups with zero total weight.', 'def weighted_averages_by_group(records):\n    weighted_totals = {}\n    weights = {}\n    for row in records:\n        if row["weight"] < 0:\n            raise ValueError("weight must be nonnegative")\n        group = row["group"]\n        weighted_totals[group] = weighted_totals.get(group, 0) + row["value"] * row["weight"]\n        weights[group] = weights.get(group, 0) + row["weight"]\n    return {group: weighted_totals[group] / weight for group, weight in weights.items() if weight}'),
    ('linear_interpolation', 'Write a Python function that linearly interpolates a query position from sorted distinct x coordinates and aligned y values, returning endpoint values outside the coordinate range.', 'def interpolate_linear(xs, ys, query):\n    if len(xs) != len(ys) or not xs:\n        raise ValueError("coordinates must align")\n    if query <= xs[0]:\n        return ys[0]\n    if query >= xs[-1]:\n        return ys[-1]\n    right = 1\n    while xs[right] < query:\n        right += 1\n    left = right - 1\n    fraction = (query - xs[left]) / (xs[right] - xs[left])\n    return ys[left] + fraction * (ys[right] - ys[left])'),
    ('piecewise_histogram', 'Write a Python function that counts numeric values into consecutive half-open bins defined by strictly increasing boundaries and returns an overflow count for values at or above the final boundary.', 'def histogram_by_boundaries(values, boundaries):\n    if len(boundaries) < 2 or any(boundaries[index] >= boundaries[index + 1] for index in range(len(boundaries) - 1)):\n        raise ValueError("boundaries must increase")\n    counts = [0] * (len(boundaries) - 1)\n    overflow = 0\n    for value in values:\n        if value < boundaries[0]:\n            continue\n        index = 0\n        while index + 1 < len(boundaries) and value >= boundaries[index + 1]:\n            index += 1\n        if index == len(counts):\n            overflow += 1\n        else:\n            counts[index] += 1\n    return counts, overflow'),
    ('round_robin_schedule', 'Write a Python function that creates a single round-robin schedule for distinct participants, uses None as a bye when necessary, and returns each round as a list of pairs.', 'def round_robin_schedule(participants):\n    players = list(participants)\n    if len(players) % 2:\n        players.append(None)\n    rounds = []\n    for _ in range(max(0, len(players) - 1)):\n        pairs = []\n        for index in range(len(players) // 2):\n            first = players[index]\n            second = players[-1 - index]\n            if first is not None and second is not None:\n                pairs.append((first, second))\n        rounds.append(pairs)\n        players = [players[0], players[-1]] + players[1:-1]\n    return rounds'),
    ('allocate_largest_remainder', 'Write a Python function that allocates an integer total proportionally to nonnegative weights using the largest-remainder method and returns allocations in input order.', 'def allocate_largest_remainder(total, weights):\n    weight_sum = sum(weights)\n    if total < 0 or weight_sum <= 0 or any(weight < 0 for weight in weights):\n        raise ValueError("invalid total or weights")\n    quotas = [total * weight / weight_sum for weight in weights]\n    allocations = [int(quota) for quota in quotas]\n    remaining = total - sum(allocations)\n    order = sorted(range(len(weights)), key=lambda index: (-(quotas[index] - allocations[index]), index))\n    for index in order[:remaining]:\n        allocations[index] += 1\n    return allocations'),
    ('directed_cycle_detection', 'Write a Python function that reports whether a directed adjacency dictionary contains a cycle, including nodes appearing only as neighbors, without mutating the graph.', 'def directed_graph_has_cycle(graph):\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    state = {}\n    def visit(node):\n        if state.get(node) == 1:\n            return True\n        if state.get(node) == 2:\n            return False\n        state[node] = 1\n        if any(visit(neighbor) for neighbor in graph.get(node, [])):\n            return True\n        state[node] = 2\n        return False\n    return any(visit(node) for node in nodes if state.get(node, 0) == 0)'),
    ('strongly_connected_components', 'Write a Python function that returns strongly connected components of a directed adjacency dictionary as sets using two depth-first passes and without mutating the graph.', 'def strongly_connected_components(graph):\n    nodes = set(graph)\n    reverse = {}\n    for node, neighbors in graph.items():\n        reverse.setdefault(node, [])\n        for neighbor in neighbors:\n            nodes.add(neighbor)\n            reverse.setdefault(neighbor, []).append(node)\n    seen = set()\n    order = []\n    def finish(node):\n        if node in seen:\n            return\n        seen.add(node)\n        for neighbor in graph.get(node, []):\n            finish(neighbor)\n        order.append(node)\n    for node in nodes:\n        finish(node)\n    seen.clear()\n    components = []\n    def collect(node, component):\n        if node in seen:\n            return\n        seen.add(node)\n        component.add(node)\n        for neighbor in reverse.get(node, []):\n            collect(neighbor, component)\n    for node in reversed(order):\n        if node not in seen:\n            component = set()\n            collect(node, component)\n            components.append(component)\n    return components'),
    ('minimum_spanning_forest', "Write a Python function that returns a minimum spanning forest from weighted undirected edges `(weight, left, right)` using Kruskal's algorithm, preserving the selected edge tuples.", 'def minimum_spanning_forest(edges):\n    nodes = {node for _, left, right in edges for node in (left, right)}\n    parent = {node: node for node in nodes}\n    rank = {node: 0 for node in nodes}\n    def find(node):\n        while parent[node] != node:\n            parent[node] = parent[parent[node]]\n            node = parent[node]\n        return node\n    selected = []\n    for edge in sorted(edges):\n        weight, left, right = edge\n        left_root, right_root = find(left), find(right)\n        if left_root == right_root:\n            continue\n        if rank[left_root] < rank[right_root]:\n            left_root, right_root = right_root, left_root\n        parent[right_root] = left_root\n        if rank[left_root] == rank[right_root]:\n            rank[left_root] += 1\n        selected.append(edge)\n    return selected'),
    ('bellman_ford', 'Write a Python function that computes shortest distances from a start node over directed weighted edges and raises ValueError when a reachable negative cycle exists.', 'def bellman_ford_distances(nodes, edges, start):\n    distances = {node: float("inf") for node in nodes}\n    distances[start] = 0\n    for _ in range(max(0, len(nodes) - 1)):\n        changed = False\n        for source, target, weight in edges:\n            if distances[source] != float("inf") and distances[source] + weight < distances[target]:\n                distances[target] = distances[source] + weight\n                changed = True\n        if not changed:\n            break\n    for source, target, weight in edges:\n        if distances[source] != float("inf") and distances[source] + weight < distances[target]:\n            raise ValueError("reachable negative cycle")\n    return {node: distance for node, distance in distances.items() if distance != float("inf")}'),
    ('all_pairs_shortest_paths', 'Write a Python function that computes all-pairs shortest distances from a square weighted matrix where None means no edge, using Floyd-Warshall without mutating the matrix.', 'def all_pairs_shortest_paths(matrix):\n    size = len(matrix)\n    if any(len(row) != size for row in matrix):\n        raise ValueError("matrix must be square")\n    distances = [[float("inf") if value is None else value for value in row] for row in matrix]\n    for index in range(size):\n        distances[index][index] = min(distances[index][index], 0)\n    for middle in range(size):\n        for source in range(size):\n            for target in range(size):\n                distances[source][target] = min(distances[source][target], distances[source][middle] + distances[middle][target])\n    return distances'),
    ('bipartite_partition', 'Write a Python function that partitions an undirected adjacency dictionary into two sets when the graph is bipartite, returns None otherwise, and handles disconnected components.', 'def bipartite_partition(graph):\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    color = {}\n    for start in nodes:\n        if start in color:\n            continue\n        color[start] = 0\n        queue = [start]\n        for node in queue:\n            for neighbor in graph.get(node, []):\n                if neighbor not in color:\n                    color[neighbor] = 1 - color[node]\n                    queue.append(neighbor)\n                elif color[neighbor] == color[node]:\n                    return None\n    return ({node for node in nodes if color[node] == 0}, {node for node in nodes if color[node] == 1})'),
    ('tree_diameter', 'Write a Python function that returns the number of edges in the diameter of a non-empty undirected tree represented by an adjacency dictionary without mutating it.', 'def tree_diameter(graph):\n    if not graph:\n        raise ValueError("tree must be non-empty")\n    def farthest(start):\n        distances = {start: 0}\n        queue = [start]\n        for node in queue:\n            for neighbor in graph.get(node, []):\n                if neighbor not in distances:\n                    distances[neighbor] = distances[node] + 1\n                    queue.append(neighbor)\n        return max(distances, key=distances.get), max(distances.values())\n    endpoint, _ = farthest(next(iter(graph)))\n    return farthest(endpoint)[1]'),
    ('rooted_tree_depths', 'Write a Python function that assigns depths from a root in a parent-to-children dictionary, rejects a node reached by more than one path, and returns a new dictionary.', 'def rooted_tree_depths(children, root):\n    depths = {root: 0}\n    stack = [root]\n    while stack:\n        node = stack.pop()\n        for child in children.get(node, []):\n            if child in depths:\n                raise ValueError("input is not a rooted tree")\n            depths[child] = depths[node] + 1\n            stack.append(child)\n    return depths'),
    ('postorder_tree_aggregation', 'Write a Python function that returns the total numeric value of every subtree in a rooted parent-to-children dictionary using a separate node-value dictionary.', 'def subtree_value_totals(children, values, root):\n    totals = {}\n    active = set()\n    def visit(node):\n        if node in active:\n            raise ValueError("cycle in tree")\n        active.add(node)\n        total = values.get(node, 0)\n        for child in children.get(node, []):\n            total += visit(child)\n        active.remove(node)\n        totals[node] = total\n        return total\n    visit(root)\n    return totals'),
    ('event_sweep_peak', 'Write a Python function that returns the maximum number of simultaneously active half-open intervals using an event sweep, treating end events before start events at equal positions.', 'def peak_interval_overlap(intervals):\n    events = []\n    for start, end in intervals:\n        if end < start:\n            raise ValueError("interval end precedes start")\n        events.append((start, 1))\n        events.append((end, -1))\n    active = best = 0\n    for _, change in sorted(events, key=lambda event: (event[0], event[1])):\n        active += change\n        best = max(best, active)\n    return best'),
    ('calendar_free_ranges', 'Write a Python function that returns free half-open ranges inside a supplied day boundary after merging busy intervals, without mutating the inputs.', 'def free_ranges(day_start, day_end, busy):\n    if day_end < day_start:\n        raise ValueError("invalid day range")\n    clipped = [(max(day_start, start), min(day_end, end)) for start, end in busy if end > day_start and start < day_end]\n    merged = []\n    for start, end in sorted(clipped):\n        if not merged or start > merged[-1][1]:\n            merged.append([start, end])\n        else:\n            merged[-1][1] = max(merged[-1][1], end)\n    free = []\n    cursor = day_start\n    for start, end in merged:\n        if cursor < start:\n            free.append((cursor, start))\n        cursor = max(cursor, end)\n    if cursor < day_end:\n        free.append((cursor, day_end))\n    return free'),
    ('minimum_meeting_rooms', 'Write a Python function that returns the minimum rooms required for half-open meeting intervals, allowing a room to be reused when one meeting ends as another starts.', 'def minimum_meeting_rooms(meetings):\n    starts = sorted(start for start, _ in meetings)\n    ends = sorted(end for _, end in meetings)\n    rooms = best = 0\n    start_index = end_index = 0\n    while start_index < len(starts):\n        if starts[start_index] >= ends[end_index]:\n            rooms -= 1\n            end_index += 1\n        else:\n            rooms += 1\n            best = max(best, rooms)\n            start_index += 1\n    return best'),
    ('monotonic_next_greater', 'Write a Python function that returns the next strictly greater value to the right of each sequence element, using None when none exists and a monotonic stack.', 'def next_greater_values(values):\n    result = [None] * len(values)\n    stack = []\n    for index, value in enumerate(values):\n        while stack and values[stack[-1]] < value:\n            result[stack.pop()] = value\n        stack.append(index)\n    return result'),
    ('stock_span', 'Write a Python function that returns, for each price, the number of consecutive days ending there whose prices are less than or equal to that price, using a stack.', 'def stock_spans(prices):\n    spans = []\n    stack = []\n    for index, price in enumerate(prices):\n        while stack and stack[-1][1] <= price:\n            stack.pop()\n        spans.append(index + 1 if not stack else index - stack[-1][0])\n        stack.append((index, price))\n    return spans'),
    ('sliding_window_maximum', 'Write a Python function that returns the maximum of every consecutive positive-width window using a monotonic index queue without mutating the sequence.', 'def sliding_window_maximum(values, width):\n    if width <= 0:\n        raise ValueError("width must be positive")\n    if width > len(values):\n        return []\n    queue = []\n    head = 0\n    result = []\n    for index, value in enumerate(values):\n        while head < len(queue) and queue[head] <= index - width:\n            head += 1\n        while len(queue) > head and values[queue[-1]] <= value:\n            queue.pop()\n        queue.append(index)\n        if index >= width - 1:\n            result.append(values[queue[head]])\n    return result'),
    ('minimum_covering_substring', 'Write a Python function that returns the shortest substring containing every character of a target with multiplicity, or an empty string when none exists.', 'def minimum_covering_substring(text, target):\n    if not target:\n        return ""\n    needed = {}\n    for character in target:\n        needed[character] = needed.get(character, 0) + 1\n    missing = len(target)\n    left = 0\n    best = None\n    for right, character in enumerate(text):\n        if needed.get(character, 0) > 0:\n            missing -= 1\n        needed[character] = needed.get(character, 0) - 1\n        while missing == 0:\n            if best is None or right - left + 1 < best[1] - best[0]:\n                best = (left, right + 1)\n            outgoing = text[left]\n            needed[outgoing] = needed.get(outgoing, 0) + 1\n            if needed[outgoing] > 0:\n                missing += 1\n            left += 1\n    return "" if best is None else text[best[0]:best[1]]'),
    ('kmp_substring_search', 'Write a Python function that returns every starting index where a non-empty pattern occurs in text, including overlaps, using prefix-function matching.', 'def substring_match_indices(text, pattern):\n    if not pattern:\n        raise ValueError("pattern must be non-empty")\n    prefix = [0] * len(pattern)\n    matched = 0\n    for index in range(1, len(pattern)):\n        while matched and pattern[index] != pattern[matched]:\n            matched = prefix[matched - 1]\n        if pattern[index] == pattern[matched]:\n            matched += 1\n        prefix[index] = matched\n    result = []\n    matched = 0\n    for index, character in enumerate(text):\n        while matched and character != pattern[matched]:\n            matched = prefix[matched - 1]\n        if character == pattern[matched]:\n            matched += 1\n        if matched == len(pattern):\n            result.append(index - len(pattern) + 1)\n            matched = prefix[matched - 1]\n    return result'),
    ('word_break', 'Write a Python function that reports whether a string can be segmented entirely into words from a supplied collection using dynamic programming.', 'def can_segment_words(text, words):\n    vocabulary = set(words)\n    reachable = [False] * (len(text) + 1)\n    reachable[0] = True\n    for end in range(1, len(text) + 1):\n        reachable[end] = any(reachable[start] and text[start:end] in vocabulary for start in range(end))\n    return reachable[-1]'),
    ('decode_count', 'Write a Python function that counts decodings of a digit string under the mapping 1 through 26 to letters, returning zero for invalid encodings.', 'def decoding_count(digits):\n    if not digits or digits[0] == "0":\n        return 0\n    previous_two = previous_one = 1\n    for index in range(1, len(digits)):\n        current = 0\n        if digits[index] != "0":\n            current += previous_one\n        if 10 <= int(digits[index - 1:index + 1]) <= 26:\n            current += previous_two\n        previous_two, previous_one = previous_one, current\n    return previous_one'),
    ('rational_addition', 'Write a Python function that adds two rational numbers represented by numerator-denominator pairs and returns a reduced pair with a positive denominator.', 'def add_rationals(first, second):\n    left_numerator, left_denominator = first\n    right_numerator, right_denominator = second\n    if left_denominator == 0 or right_denominator == 0:\n        raise ValueError("zero denominator")\n    numerator = left_numerator * right_denominator + right_numerator * left_denominator\n    denominator = left_denominator * right_denominator\n    a, b = abs(numerator), abs(denominator)\n    while b:\n        a, b = b, a % b\n    divisor = a or 1\n    numerator //= divisor\n    denominator //= divisor\n    if denominator < 0:\n        numerator, denominator = -numerator, -denominator\n    return numerator, denominator'),
    ('sparse_matrix_multiply', 'Write a Python function that multiplies sparse matrices represented by `(row, column)` dictionaries and supplied dimensions, returning only nonzero result entries.', 'def multiply_sparse_matrices(left, right, left_shape, right_shape):\n    if left_shape[1] != right_shape[0]:\n        raise ValueError("incompatible shapes")\n    right_rows = {}\n    for (row, column), value in right.items():\n        right_rows.setdefault(row, []).append((column, value))\n    result = {}\n    for (row, inner), left_value in left.items():\n        for column, right_value in right_rows.get(inner, []):\n            key = (row, column)\n            result[key] = result.get(key, 0) + left_value * right_value\n            if result[key] == 0:\n                del result[key]\n    return result'),
    ('moving_z_scores', 'Write a Python function that returns z-scores for each complete positive-width numeric window, using the final value in each window and returning zero when variance is zero.', 'def moving_z_scores(values, width):\n    if width <= 0:\n        raise ValueError("width must be positive")\n    result = []\n    for end in range(width, len(values) + 1):\n        window = values[end - width:end]\n        mean = sum(window) / width\n        variance = sum((value - mean) ** 2 for value in window) / width\n        result.append(0 if variance == 0 else (window[-1] - mean) / variance ** 0.5)\n    return result'),
    ('reservoir_without_randomness', 'Write a Python function that deterministically selects evenly distributed representatives from a sequence for a requested positive sample size, preserving order and returning all values when the sample is large enough.', 'def evenly_spaced_sample(values, size):\n    if size <= 0:\n        raise ValueError("size must be positive")\n    if size >= len(values):\n        return list(values)\n    if size == 1:\n        return [values[0]]\n    return [values[index * (len(values) - 1) // (size - 1)] for index in range(size)]'),
    ('stable_multikey_sort', 'Write a Python function that stably sorts copied records by a sequence of `(field, descending)` specifications without mutating the records.', 'def stable_multikey_sort(records, specifications):\n    result = [row.copy() for row in records]\n    for field, descending in reversed(specifications):\n        result.sort(key=lambda row: row[field], reverse=descending)\n    return result'),
    ('postfix_expression', 'Write a Python function that evaluates a whitespace-tokenized postfix expression containing integers and the operators +, -, *, and /, requiring exact integer division.', 'def evaluate_postfix(tokens):\n    stack = []\n    for token in tokens:\n        if token not in {"+", "-", "*", "/"}:\n            stack.append(int(token))\n            continue\n        if len(stack) < 2:\n            raise ValueError("invalid postfix expression")\n        right = stack.pop()\n        left = stack.pop()\n        if token == "+":\n            stack.append(left + right)\n        elif token == "-":\n            stack.append(left - right)\n        elif token == "*":\n            stack.append(left * right)\n        elif right == 0 or left % right:\n            raise ValueError("division must be exact and nonzero")\n        else:\n            stack.append(left // right)\n    if len(stack) != 1:\n        raise ValueError("invalid postfix expression")\n    return stack[0]'),
    ('infix_to_postfix', 'Write a Python function that converts tokens from an infix expression containing operands, parentheses, and +, -, *, / operators into postfix order.', 'def infix_to_postfix(tokens):\n    precedence = {"+": 1, "-": 1, "*": 2, "/": 2}\n    output = []\n    operators = []\n    for token in tokens:\n        if token == "(":\n            operators.append(token)\n        elif token == ")":\n            while operators and operators[-1] != "(":\n                output.append(operators.pop())\n            if not operators:\n                raise ValueError("unbalanced parentheses")\n            operators.pop()\n        elif token in precedence:\n            while operators and operators[-1] in precedence and precedence[operators[-1]] >= precedence[token]:\n                output.append(operators.pop())\n            operators.append(token)\n        else:\n            output.append(token)\n    while operators:\n        if operators[-1] == "(":\n            raise ValueError("unbalanced parentheses")\n        output.append(operators.pop())\n    return output'),
    ('wildcard_matching', 'Write a Python function that reports whether an entire string matches a pattern where `?` matches one character and `*` matches any sequence, using dynamic programming.', 'def wildcard_matches(text, pattern):\n    previous = [True] + [False] * len(text)\n    for symbol in pattern:\n        current = [previous[0] and symbol == "*"]\n        for index, character in enumerate(text, 1):\n            if symbol == "*":\n                current.append(previous[index] or current[-1])\n            else:\n                current.append(previous[index - 1] and (symbol == "?" or symbol == character))\n        previous = current\n    return previous[-1]'),
    ('longest_palindrome', 'Write a Python function that returns the earliest longest palindromic substring by expanding around every possible center.', 'def longest_palindromic_substring(text):\n    best_start = best_end = 0\n    for center in range(len(text)):\n        for left, right in ((center, center), (center, center + 1)):\n            while left >= 0 and right < len(text) and text[left] == text[right]:\n                if right - left > best_end - best_start:\n                    best_start, best_end = left, right\n                left -= 1\n                right += 1\n    return text[best_start:best_end + 1]'),
    ('canonical_path', 'Write a Python function that normalizes an absolute slash-separated path by removing empty and dot components and resolving double-dot components without moving above root.', 'def canonical_absolute_path(path):\n    if not path.startswith("/"):\n        raise ValueError("path must be absolute")\n    components = []\n    for component in path.split("/"):\n        if component in {"", "."}:\n            continue\n        if component == "..":\n            if components:\n                components.pop()\n        else:\n            components.append(component)\n    return "/" + "/".join(components)'),
    ('semantic_version_compare', 'Write a Python function that compares two dot-separated nonnegative integer version strings after ignoring trailing zero components, returning -1, 0, or 1.', 'def compare_versions(first, second):\n    left = [int(part) for part in first.split(".")]\n    right = [int(part) for part in second.split(".")]\n    width = max(len(left), len(right))\n    left.extend([0] * (width - len(left)))\n    right.extend([0] * (width - len(right)))\n    if left < right:\n        return -1\n    if left > right:\n        return 1\n    return 0'),
    ('query_string_parse', 'Write a Python function that parses an ampersand-separated query string into a dictionary of key-to-list-of-values, treating fields without `=` as having an empty value.', 'def parse_query_string(query):\n    result = {}\n    if not query:\n        return result\n    for field in query.split("&"):\n        key, separator, value = field.partition("=")\n        result.setdefault(key, []).append(value if separator else "")\n    return result'),
    ('table_pivot', 'Write a Python function that pivots records containing row, column, and value fields into nested dictionaries and raises an error for duplicate row-column cells.', 'def pivot_records(records):\n    result = {}\n    for record in records:\n        row = record["row"]\n        column = record["column"]\n        cells = result.setdefault(row, {})\n        if column in cells:\n            raise ValueError("duplicate pivot cell")\n        cells[column] = record["value"]\n    return result'),
    ('table_unpivot', 'Write a Python function that converts nested row-to-column dictionaries into records with row, column, and value fields, preserving dictionary iteration order.', 'def unpivot_table(table):\n    records = []\n    for row, columns in table.items():\n        for column, value in columns.items():\n            records.append({"row": row, "column": column, "value": value})\n    return records'),
    ('relational_left_join', 'Write a Python function that left-joins records to indexed lookup records using configurable keys, returns one merged copy per match, and retains unmatched left records.', 'def left_join_records(left_rows, right_rows, left_key, right_key):\n    index = {}\n    for row in right_rows:\n        index.setdefault(row[right_key], []).append(row)\n    result = []\n    for left in left_rows:\n        matches = index.get(left[left_key])\n        if not matches:\n            result.append(left.copy())\n            continue\n        for right in matches:\n            merged = left.copy()\n            merged.update(right)\n            result.append(merged)\n    return result'),
    ('dense_rank_groups', 'Write a Python function that returns copied records with a dense rank field assigned within each group by descending score, giving equal scores equal ranks.', 'def dense_rank_by_group(records):\n    grouped = {}\n    for record in records:\n        grouped.setdefault(record["group"], []).append(record)\n    result = []\n    for rows in grouped.values():\n        previous_score = None\n        rank = 0\n        for record in sorted(rows, key=lambda row: row["score"], reverse=True):\n            if previous_score is None or record["score"] != previous_score:\n                rank += 1\n                previous_score = record["score"]\n            copied = record.copy()\n            copied["rank"] = rank\n            result.append(copied)\n    return result'),
    ('exponential_moving_average', 'Write a Python function that returns the exponential moving average after every numeric value using a smoothing factor in the interval `(0, 1]`.', 'def exponential_moving_averages(values, alpha):\n    if not 0 < alpha <= 1:\n        raise ValueError("alpha must be in (0, 1]")\n    if not values:\n        return []\n    result = [values[0]]\n    for value in values[1:]:\n        result.append(alpha * value + (1 - alpha) * result[-1])\n    return result'),
    ('linear_missing_values', 'Write a Python function that fills interior None values in a numeric sequence by linear interpolation between surrounding known values while leaving leading and trailing None values unchanged.', 'def interpolate_missing_values(values):\n    result = list(values)\n    known = [index for index, value in enumerate(values) if value is not None]\n    for left_index, right_index in zip(known, known[1:]):\n        left_value = values[left_index]\n        right_value = values[right_index]\n        gap = right_index - left_index\n        for offset in range(1, gap):\n            result[left_index + offset] = left_value + (right_value - left_value) * offset / gap\n    return result'),
    ('interquartile_outliers', "Write a Python function that returns values strictly outside Tukey's 1.5-IQR fences, using medians of the lower and upper halves and preserving input order.", 'def interquartile_outliers(values):\n    if len(values) < 4:\n        return []\n    ordered = sorted(values)\n    middle = len(ordered) // 2\n    lower = ordered[:middle]\n    upper = ordered[(len(ordered) + 1) // 2:]\n    def median(items):\n        center = len(items) // 2\n        return items[center] if len(items) % 2 else (items[center - 1] + items[center]) / 2\n    first_quartile = median(lower)\n    third_quartile = median(upper)\n    spread = third_quartile - first_quartile\n    low, high = first_quartile - 1.5 * spread, third_quartile + 1.5 * spread\n    return [value for value in values if value < low or value > high]'),
    ('linear_quantile', 'Write a Python function that computes a quantile from a non-empty numeric sequence using linear interpolation between adjacent sorted values for a fraction from zero through one.', 'def linear_quantile(values, fraction):\n    if not values or not 0 <= fraction <= 1:\n        raise ValueError("invalid values or fraction")\n    ordered = sorted(values)\n    position = fraction * (len(ordered) - 1)\n    lower = int(position)\n    upper = min(lower + 1, len(ordered) - 1)\n    weight = position - lower\n    return ordered[lower] * (1 - weight) + ordered[upper] * weight'),
    ('median_sorted_sequences', 'Write a Python function that returns the median of two ascending numeric sequences using a partition-based binary search and rejects two empty inputs.', 'def median_of_sorted_sequences(first, second):\n    if len(first) > len(second):\n        first, second = second, first\n    if not second:\n        raise ValueError("at least one value is required")\n    total = len(first) + len(second)\n    half = (total + 1) // 2\n    left, right = 0, len(first)\n    while left <= right:\n        first_cut = (left + right) // 2\n        second_cut = half - first_cut\n        first_left = float("-inf") if first_cut == 0 else first[first_cut - 1]\n        first_right = float("inf") if first_cut == len(first) else first[first_cut]\n        second_left = float("-inf") if second_cut == 0 else second[second_cut - 1]\n        second_right = float("inf") if second_cut == len(second) else second[second_cut]\n        if first_left <= second_right and second_left <= first_right:\n            if total % 2:\n                return max(first_left, second_left)\n            return (max(first_left, second_left) + min(first_right, second_right)) / 2\n        if first_left > second_right:\n            right = first_cut - 1\n        else:\n            left = first_cut + 1\n    raise ValueError("inputs must be sorted")'),
    ('k_closest_values', 'Write a Python function that returns the k values closest to a target ordered by distance, then value, then original position, without mutating the input.', 'def k_closest_values(values, target, k):\n    if k < 0:\n        raise ValueError("k must be nonnegative")\n    ranked = sorted(enumerate(values), key=lambda item: (abs(item[1] - target), item[1], item[0]))\n    return [value for _, value in ranked[:k]]'),
    ('quickselect', 'Write a Python function that returns the zero-based kth smallest numeric value using iterative partitioning on a copied list and rejects an invalid index.', 'def kth_smallest(values, k):\n    if not 0 <= k < len(values):\n        raise ValueError("invalid k")\n    items = list(values)\n    left, right = 0, len(items) - 1\n    while True:\n        pivot = items[right]\n        boundary = left\n        for index in range(left, right):\n            if items[index] <= pivot:\n                items[boundary], items[index] = items[index], items[boundary]\n                boundary += 1\n        items[boundary], items[right] = items[right], items[boundary]\n        if boundary == k:\n            return items[boundary]\n        if boundary < k:\n            left = boundary + 1\n        else:\n            right = boundary - 1'),
    ('stable_counting_sort', 'Write a Python function that stably sorts records by a nonnegative integer key bounded by a supplied maximum, returning copied records and rejecting out-of-range keys.', 'def stable_counting_sort(records, key, maximum):\n    buckets = [[] for _ in range(maximum + 1)]\n    for record in records:\n        value = record[key]\n        if not 0 <= value <= maximum:\n            raise ValueError("key outside range")\n        buckets[value].append(record.copy())\n    return [record for bucket in buckets for record in bucket]'),
    ('radix_sort', 'Write a Python function that sorts nonnegative integers using stable least-significant-digit radix passes without mutating the input.', 'def radix_sort_nonnegative(values):\n    if any(value < 0 for value in values):\n        raise ValueError("values must be nonnegative")\n    result = list(values)\n    place = 1\n    maximum = max(result, default=0)\n    while maximum // place:\n        buckets = [[] for _ in range(10)]\n        for value in result:\n            buckets[(value // place) % 10].append(value)\n        result = [value for bucket in buckets for value in bucket]\n        place *= 10\n    return result'),
    ('inversion_count', 'Write a Python function that counts index pairs appearing out of ascending order using merge-sort counting without mutating the sequence.', 'def count_inversions(values):\n    def sort_count(items):\n        if len(items) < 2:\n            return items, 0\n        middle = len(items) // 2\n        left, left_count = sort_count(items[:middle])\n        right, right_count = sort_count(items[middle:])\n        merged = []\n        inversions = left_count + right_count\n        left_index = right_index = 0\n        while left_index < len(left) and right_index < len(right):\n            if left[left_index] <= right[right_index]:\n                merged.append(left[left_index])\n                left_index += 1\n            else:\n                merged.append(right[right_index])\n                right_index += 1\n                inversions += len(left) - left_index\n        return merged + left[left_index:] + right[right_index:], inversions\n    return sort_count(list(values))[1]'),
    ('stable_merge_sort', 'Write a Python function that stably sorts a sequence by an optional key function using recursive merge sort and does not mutate the input.', 'def stable_merge_sort(values, key=lambda value: value):\n    if len(values) < 2:\n        return list(values)\n    middle = len(values) // 2\n    left = stable_merge_sort(values[:middle], key)\n    right = stable_merge_sort(values[middle:], key)\n    merged = []\n    left_index = right_index = 0\n    while left_index < len(left) and right_index < len(right):\n        if key(left[left_index]) <= key(right[right_index]):\n            merged.append(left[left_index])\n            left_index += 1\n        else:\n            merged.append(right[right_index])\n            right_index += 1\n    return merged + left[left_index:] + right[right_index:]'),
    ('weighted_interval_schedule', 'Write a Python function that returns the maximum total weight from mutually nonoverlapping half-open intervals using dynamic programming.', 'def maximum_interval_weight(intervals):\n    ordered = sorted(intervals, key=lambda item: item[1])\n    ends = [end for _, end, _ in ordered]\n    best = [0]\n    for index, (start, _, weight) in enumerate(ordered):\n        left, right = 0, index\n        while left < right:\n            middle = (left + right) // 2\n            if ends[middle] <= start:\n                left = middle + 1\n            else:\n                right = middle\n        compatible = left if left < index and ends[left] <= start else left - 1\n        best.append(max(best[-1], weight + best[compatible + 1]))\n    return best[-1]'),
    ('dag_critical_path', 'Write a Python function that returns the longest weighted path length from any source through a directed acyclic adjacency dictionary whose edges are `(neighbor, weight)` pairs.', 'def dag_critical_path(graph):\n    nodes = set(graph)\n    indegree = {}\n    for node, edges in graph.items():\n        indegree.setdefault(node, 0)\n        for neighbor, _ in edges:\n            nodes.add(neighbor)\n            indegree[neighbor] = indegree.get(neighbor, 0) + 1\n    ready = [node for node in nodes if indegree.get(node, 0) == 0]\n    distance = {node: 0 for node in nodes}\n    processed = 0\n    while ready:\n        node = ready.pop()\n        processed += 1\n        for neighbor, weight in graph.get(node, []):\n            distance[neighbor] = max(distance[neighbor], distance[node] + weight)\n            indegree[neighbor] -= 1\n            if indegree[neighbor] == 0:\n                ready.append(neighbor)\n    if processed != len(nodes):\n        raise ValueError("graph contains a cycle")\n    return max(distance.values(), default=0)'),
    ('maximum_flow', 'Write a Python function that computes maximum flow from source to sink in a directed capacity dictionary using augmenting breadth-first paths without mutating capacities.', 'def maximum_flow(capacities, source, sink):\n    residual = {}\n    for node, edges in capacities.items():\n        residual.setdefault(node, {})\n        for neighbor, capacity in edges.items():\n            residual[node][neighbor] = capacity\n            residual.setdefault(neighbor, {}).setdefault(node, 0)\n    total = 0\n    while True:\n        parent = {source: None}\n        queue = [source]\n        for node in queue:\n            for neighbor, capacity in residual.get(node, {}).items():\n                if capacity > 0 and neighbor not in parent:\n                    parent[neighbor] = node\n                    queue.append(neighbor)\n        if sink not in parent:\n            return total\n        amount = float("inf")\n        node = sink\n        while parent[node] is not None:\n            amount = min(amount, residual[parent[node]][node])\n            node = parent[node]\n        node = sink\n        while parent[node] is not None:\n            previous = parent[node]\n            residual[previous][node] -= amount\n            residual[node][previous] += amount\n            node = previous\n        total += amount'),
    ('transitive_closure', 'Write a Python function that returns the set of nodes reachable from every node in a directed adjacency dictionary, including neighbor-only nodes and excluding each node itself unless a cycle returns to it.', 'def directed_transitive_closure(graph):\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    closure = {}\n    for start in nodes:\n        reached = set()\n        stack = list(graph.get(start, []))\n        while stack:\n            node = stack.pop()\n            if node in reached:\n                continue\n            reached.add(node)\n            stack.extend(graph.get(node, []))\n        closure[start] = reached\n    return closure'),
    ('edit_script', 'Write a Python function that returns an insertion-and-deletion edit script transforming one sequence into another by tracing a longest-common-subsequence table.', 'def insertion_deletion_script(first, second):\n    table = [[0] * (len(second) + 1) for _ in range(len(first) + 1)]\n    for left in range(len(first) - 1, -1, -1):\n        for right in range(len(second) - 1, -1, -1):\n            table[left][right] = 1 + table[left + 1][right + 1] if first[left] == second[right] else max(table[left + 1][right], table[left][right + 1])\n    script = []\n    left = right = 0\n    while left < len(first) or right < len(second):\n        if left < len(first) and right < len(second) and first[left] == second[right]:\n            script.append(("keep", first[left]))\n            left += 1\n            right += 1\n        elif right < len(second) and (left == len(first) or table[left][right + 1] >= table[left + 1][right]):\n            script.append(("insert", second[right]))\n            right += 1\n        else:\n            script.append(("delete", first[left]))\n            left += 1\n    return script'),
    ('checksum_modulus', 'Write a Python function that computes a positional modular checksum for integer values using repeating positive weights and a positive modulus.', 'def positional_checksum(values, weights, modulus):\n    if not weights or any(weight <= 0 for weight in weights) or modulus <= 0:\n        raise ValueError("invalid weights or modulus")\n    return sum(value * weights[index % len(weights)] for index, value in enumerate(values)) % modulus'),
    ('rate_limit_windows', 'Write a Python function that reports which ascending event timestamps are admitted by a sliding-window rate limit, allowing at most a supplied count in each positive-width interval.', 'def sliding_window_admissions(timestamps, limit, width):\n    if limit < 0 or width <= 0:\n        raise ValueError("invalid limit or width")\n    admitted = []\n    active = []\n    head = 0\n    for timestamp in timestamps:\n        while head < len(active) and active[head] <= timestamp - width:\n            head += 1\n        allowed = len(active) - head < limit\n        admitted.append(allowed)\n        if allowed:\n            active.append(timestamp)\n    return admitted'),
    ('token_bucket_simulation', 'Write a Python function that reports admissions for ascending `(timestamp, cost)` requests under a token bucket with positive capacity and refill rate, starting full.', 'def token_bucket_admissions(requests, capacity, refill_rate):\n    if capacity <= 0 or refill_rate < 0:\n        raise ValueError("invalid bucket settings")\n    tokens = capacity\n    previous_time = requests[0][0] if requests else 0\n    result = []\n    for timestamp, cost in requests:\n        if timestamp < previous_time or cost < 0:\n            raise ValueError("invalid request sequence")\n        tokens = min(capacity, tokens + (timestamp - previous_time) * refill_rate)\n        allowed = cost <= tokens\n        result.append(allowed)\n        if allowed:\n            tokens -= cost\n        previous_time = timestamp\n    return result'),
    ('deficit_round_robin', 'Write a Python function that schedules queued `(item, cost)` entries across named queues using deficit round robin with a positive quantum and returns the service order.', 'def deficit_round_robin(queues, quantum):\n    if quantum <= 0:\n        raise ValueError("quantum must be positive")\n    pending = {name: list(items) for name, items in queues.items()}\n    deficits = {name: 0 for name in pending}\n    result = []\n    while any(pending.values()):\n        progressed = False\n        for name, items in pending.items():\n            if not items:\n                continue\n            deficits[name] += quantum\n            while items and items[0][1] <= deficits[name]:\n                item, cost = items.pop(0)\n                if cost < 0:\n                    raise ValueError("cost must be nonnegative")\n                deficits[name] -= cost\n                result.append((name, item))\n                progressed = True\n        if not progressed and all(items and items[0][1] > deficits[name] + quantum for name, items in pending.items() if items):\n            continue\n    return result'),
    ('consistent_hash_assignment', 'Write a Python function that assigns integer hash positions to the first clockwise node position on a sorted ring, wrapping to the first node, without mutating either sequence.', 'def assign_hash_ring(positions, node_positions):\n    if not node_positions:\n        raise ValueError("ring must contain a node")\n    ring = sorted(node_positions)\n    assignments = []\n    for position in positions:\n        left, right = 0, len(ring)\n        while left < right:\n            middle = (left + right) // 2\n            if ring[middle] < position:\n                left = middle + 1\n            else:\n                right = middle\n        assignments.append(ring[left] if left < len(ring) else ring[0])\n    return assignments'),
    ('fenwick_queries', 'Write a Python function that processes point-add and inclusive-prefix-sum operations over an initial numeric sequence using a Fenwick tree.', 'def process_fenwick_operations(values, operations):\n    tree = [0] * (len(values) + 1)\n    def add(index, amount):\n        index += 1\n        while index < len(tree):\n            tree[index] += amount\n            index += index & -index\n    def prefix(index):\n        total = 0\n        index += 1\n        while index > 0:\n            total += tree[index]\n            index -= index & -index\n        return total\n    for index, value in enumerate(values):\n        add(index, value)\n    answers = []\n    for operation in operations:\n        if operation[0] == "add":\n            add(operation[1], operation[2])\n        elif operation[0] == "prefix":\n            answers.append(prefix(operation[1]))\n        else:\n            raise ValueError("unknown operation")\n    return answers'),
    ('difference_range_updates', 'Write a Python function that applies inclusive range-add updates to a fixed-length zero sequence using a difference array and returns the final values.', 'def apply_range_additions(length, updates):\n    if length < 0:\n        raise ValueError("length must be nonnegative")\n    difference = [0] * (length + 1)\n    for start, end, amount in updates:\n        if not 0 <= start <= end < length:\n            raise ValueError("invalid range")\n        difference[start] += amount\n        difference[end + 1] -= amount\n    result = []\n    current = 0\n    for index in range(length):\n        current += difference[index]\n        result.append(current)\n    return result'),
    ('two_dimensional_prefix_queries', 'Write a Python function that answers inclusive rectangular sum queries over a rectangular numeric matrix using a two-dimensional prefix table.', 'def rectangle_sum_queries(matrix, queries):\n    if not matrix:\n        return [0 for _ in queries]\n    rows, columns = len(matrix), len(matrix[0])\n    if any(len(row) != columns for row in matrix):\n        raise ValueError("matrix must be rectangular")\n    prefix = [[0] * (columns + 1) for _ in range(rows + 1)]\n    for row in range(rows):\n        running = 0\n        for column in range(columns):\n            running += matrix[row][column]\n            prefix[row + 1][column + 1] = prefix[row][column + 1] + running\n    result = []\n    for top, left, bottom, right in queries:\n        if not (0 <= top <= bottom < rows and 0 <= left <= right < columns):\n            raise ValueError("invalid rectangle")\n        result.append(prefix[bottom + 1][right + 1] - prefix[top][right + 1] - prefix[bottom + 1][left] + prefix[top][left])\n    return result'),
    ('sparse_table_minimum', 'Write a Python function that answers inclusive static range-minimum queries by building a sparse table without mutating the numeric sequence.', 'def static_range_minimums(values, queries):\n    if not values:\n        raise ValueError("values must be non-empty")\n    table = [list(values)]\n    width = 2\n    while width <= len(values):\n        half = width // 2\n        previous = table[-1]\n        table.append([min(previous[index], previous[index + half]) for index in range(len(values) - width + 1)])\n        width *= 2\n    answers = []\n    for left, right in queries:\n        if not 0 <= left <= right < len(values):\n            raise ValueError("invalid range")\n        power = (right - left + 1).bit_length() - 1\n        span = 1 << power\n        answers.append(min(table[power][left], table[power][right - span + 1]))\n    return answers'),
    ('iterative_segment_tree', 'Write a Python function that processes point replacements and half-open range-sum queries using an iterative segment tree over a copied numeric sequence.', 'def process_segment_tree(values, operations):\n    size = len(values)\n    tree = [0] * size + list(values)\n    for index in range(size - 1, 0, -1):\n        tree[index] = tree[index * 2] + tree[index * 2 + 1]\n    answers = []\n    for operation in operations:\n        if operation[0] == "set":\n            position = operation[1] + size\n            tree[position] = operation[2]\n            while position > 1:\n                position //= 2\n                tree[position] = tree[position * 2] + tree[position * 2 + 1]\n        elif operation[0] == "sum":\n            left, right = operation[1] + size, operation[2] + size\n            total = 0\n            while left < right:\n                if left % 2:\n                    total += tree[left]\n                    left += 1\n                if right % 2:\n                    right -= 1\n                    total += tree[right]\n                left //= 2\n                right //= 2\n            answers.append(total)\n        else:\n            raise ValueError("unknown operation")\n    return answers'),
    ('binary_heap_schedule', 'Write a Python function that processes enqueue and dequeue operations for a minimum-priority queue, resolving equal priorities by insertion order and returning dequeued payloads.', 'def process_priority_queue(operations):\n    heap = []\n    order = 0\n    result = []\n    def push(item):\n        heap.append(item)\n        index = len(heap) - 1\n        while index:\n            parent = (index - 1) // 2\n            if heap[parent] <= heap[index]:\n                break\n            heap[parent], heap[index] = heap[index], heap[parent]\n            index = parent\n    for operation in operations:\n        if operation[0] == "enqueue":\n            push((operation[1], order, operation[2]))\n            order += 1\n        elif operation[0] == "dequeue":\n            if not heap:\n                raise ValueError("empty queue")\n            heap[0], heap[-1] = heap[-1], heap[0]\n            result.append(heap.pop()[2])\n            index = 0\n            while index * 2 + 1 < len(heap):\n                child = index * 2 + 1\n                if child + 1 < len(heap) and heap[child + 1] < heap[child]:\n                    child += 1\n                if heap[index] <= heap[child]:\n                    break\n                heap[index], heap[child] = heap[child], heap[index]\n                index = child\n        else:\n            raise ValueError("unknown operation")\n    return result'),
    ('lru_access_simulation', 'Write a Python function that simulates a positive-capacity least-recently-used cache for key accesses and returns the keys from least to most recently used at the end.', 'def simulate_lru_cache(accesses, capacity):\n    if capacity <= 0:\n        raise ValueError("capacity must be positive")\n    order = []\n    present = set()\n    for key in accesses:\n        if key in present:\n            order.remove(key)\n        else:\n            present.add(key)\n            if len(order) == capacity:\n                present.remove(order.pop(0))\n        order.append(key)\n    return order'),
    ('trie_prefix_counts', 'Write a Python function that returns how many supplied words begin with each query prefix by constructing a character trie with subtree counts.', 'def prefix_word_counts(words, prefixes):\n    root = {}\n    for word in words:\n        node = root\n        node[None] = node.get(None, 0) + 1\n        for character in word:\n            node = node.setdefault(character, {})\n            node[None] = node.get(None, 0) + 1\n    result = []\n    for prefix in prefixes:\n        node = root\n        for character in prefix:\n            if character not in node:\n                node = None\n                break\n            node = node[character]\n        result.append(0 if node is None else node.get(None, 0))\n    return result'),
    ('suffix_array', 'Write a Python function that returns the starting indices of all suffixes of a string in lexicographic order using iterative rank doubling.', 'def suffix_array(text):\n    size = len(text)\n    order = list(range(size))\n    ranks = [ord(character) for character in text]\n    width = 1\n    while width < size:\n        order.sort(key=lambda index: (ranks[index], ranks[index + width] if index + width < size else -1))\n        updated = [0] * size\n        for position in range(1, size):\n            previous, current = order[position - 1], order[position]\n            previous_key = (ranks[previous], ranks[previous + width] if previous + width < size else -1)\n            current_key = (ranks[current], ranks[current + width] if current + width < size else -1)\n            updated[current] = updated[previous] + (current_key != previous_key)\n        ranks = updated\n        width *= 2\n    return order'),
    ('z_pattern_matches', 'Write a Python function that returns every starting index of a non-empty pattern in text by computing Z-values over a combined sequence.', 'def z_match_indices(text, pattern):\n    if not pattern:\n        raise ValueError("pattern must be non-empty")\n    combined = list(pattern) + [None] + list(text)\n    z = [0] * len(combined)\n    left = right = 0\n    for index in range(1, len(combined)):\n        if index <= right:\n            z[index] = min(right - index + 1, z[index - left])\n        while index + z[index] < len(combined) and combined[z[index]] == combined[index + z[index]]:\n            z[index] += 1\n        if index + z[index] - 1 > right:\n            left, right = index, index + z[index] - 1\n    offset = len(pattern) + 1\n    return [index - offset for index in range(offset, len(combined)) if z[index] == len(pattern)]'),
    ('rolling_hash_matches', 'Write a Python function that returns every occurrence of a non-empty lowercase pattern in lowercase text using a rolling polynomial hash and direct collision verification.', 'def rolling_hash_match_indices(text, pattern):\n    if not pattern:\n        raise ValueError("pattern must be non-empty")\n    if len(pattern) > len(text):\n        return []\n    base, modulus = 257, 1000000007\n    power = pow(base, len(pattern) - 1, modulus)\n    target_hash = window_hash = 0\n    for pattern_character, text_character in zip(pattern, text):\n        target_hash = (target_hash * base + ord(pattern_character)) % modulus\n        window_hash = (window_hash * base + ord(text_character)) % modulus\n    result = []\n    for start in range(len(text) - len(pattern) + 1):\n        if window_hash == target_hash and text[start:start + len(pattern)] == pattern:\n            result.append(start)\n        if start + len(pattern) < len(text):\n            window_hash = (window_hash - ord(text[start]) * power) % modulus\n            window_hash = (window_hash * base + ord(text[start + len(pattern)])) % modulus\n    return result'),
    ('minimum_string_rotation', 'Write a Python function that returns the lexicographically smallest rotation of a non-empty string using a two-candidate linear scan.', 'def minimum_string_rotation(text):\n    if not text:\n        raise ValueError("text must be non-empty")\n    doubled = text + text\n    first, second, offset = 0, 1, 0\n    while first < len(text) and second < len(text) and offset < len(text):\n        if doubled[first + offset] == doubled[second + offset]:\n            offset += 1\n            continue\n        if doubled[first + offset] > doubled[second + offset]:\n            first = first + offset + 1\n            if first == second:\n                first += 1\n        else:\n            second = second + offset + 1\n            if first == second:\n                second += 1\n        offset = 0\n    start = min(first, second)\n    return doubled[start:start + len(text)]'),
    ('word_ladder_length', 'Write a Python function that returns the number of words in the shortest one-letter-change path between equal-length start and goal words using a supplied dictionary, or zero when impossible.', 'def word_ladder_length(start, goal, words):\n    if len(start) != len(goal):\n        return 0\n    remaining = {word for word in words if len(word) == len(start)}\n    if goal not in remaining:\n        return 0\n    queue = [(start, 1)]\n    remaining.discard(start)\n    position = 0\n    while position < len(queue):\n        word, distance = queue[position]\n        position += 1\n        if word == goal:\n            return distance\n        neighbors = [candidate for candidate in remaining if sum(left != right for left, right in zip(word, candidate)) == 1]\n        for neighbor in neighbors:\n            remaining.remove(neighbor)\n            queue.append((neighbor, distance + 1))\n    return 0'),
    ('eulerian_trail', 'Write a Python function that returns an Eulerian trail through directed edges as a node list using every edge exactly once, or raises ValueError when the supplied start cannot cover all edges.', 'def directed_eulerian_trail(edges, start):\n    adjacency = {}\n    for source, target in edges:\n        adjacency.setdefault(source, []).append(target)\n    for targets in adjacency.values():\n        targets.reverse()\n    stack = [start]\n    trail = []\n    while stack:\n        node = stack[-1]\n        if adjacency.get(node):\n            stack.append(adjacency[node].pop())\n        else:\n            trail.append(stack.pop())\n    trail.reverse()\n    if len(trail) != len(edges) + 1:\n        raise ValueError("edges do not form a trail from start")\n    return trail'),
    ('undirected_bridges', 'Write a Python function that returns every bridge edge in an undirected adjacency dictionary using discovery and low-link times.', 'def undirected_bridge_edges(graph):\n    discovery = {}\n    low = {}\n    bridges = []\n    time = 0\n    def visit(node, parent):\n        nonlocal time\n        discovery[node] = low[node] = time\n        time += 1\n        for neighbor in graph.get(node, []):\n            if neighbor == parent:\n                continue\n            if neighbor not in discovery:\n                visit(neighbor, node)\n                low[node] = min(low[node], low[neighbor])\n                if low[neighbor] > discovery[node]:\n                    bridges.append((node, neighbor))\n            else:\n                low[node] = min(low[node], discovery[neighbor])\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    for node in nodes:\n        if node not in discovery:\n            visit(node, None)\n    return bridges'),
    ('articulation_points', 'Write a Python function that returns articulation points of an undirected adjacency dictionary using depth-first discovery and low-link values.', 'def articulation_points(graph):\n    discovery = {}\n    low = {}\n    result = set()\n    time = 0\n    def visit(node, parent):\n        nonlocal time\n        discovery[node] = low[node] = time\n        time += 1\n        children = 0\n        for neighbor in graph.get(node, []):\n            if neighbor == parent:\n                continue\n            if neighbor not in discovery:\n                children += 1\n                visit(neighbor, node)\n                low[node] = min(low[node], low[neighbor])\n                if parent is not None and low[neighbor] >= discovery[node]:\n                    result.add(node)\n            else:\n                low[node] = min(low[node], discovery[neighbor])\n        if parent is None and children > 1:\n            result.add(node)\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    for node in nodes:\n        if node not in discovery:\n            visit(node, None)\n    return result'),
    ('a_star_grid', 'Write a Python function that returns a shortest four-directional path between open cells in a rectangular zero-one grid using Manhattan-distance A-star search, or an empty list when unreachable.', 'def a_star_grid_path(grid, start, goal):\n    frontier = [(0, 0, start)]\n    parent = {start: None}\n    cost = {start: 0}\n    while frontier:\n        frontier.sort(reverse=True)\n        _, distance, cell = frontier.pop()\n        if distance != cost[cell]:\n            continue\n        if cell == goal:\n            path = []\n            while cell is not None:\n                path.append(cell)\n                cell = parent[cell]\n            return list(reversed(path))\n        row, column = cell\n        for neighbor in ((row - 1, column), (row + 1, column), (row, column - 1), (row, column + 1)):\n            next_row, next_column = neighbor\n            if 0 <= next_row < len(grid) and 0 <= next_column < len(grid[0]) and grid[next_row][next_column] == 0:\n                candidate = distance + 1\n                if candidate < cost.get(neighbor, float("inf")):\n                    cost[neighbor] = candidate\n                    parent[neighbor] = cell\n                    priority = candidate + abs(next_row - goal[0]) + abs(next_column - goal[1])\n                    frontier.append((priority, candidate, neighbor))\n    return []'),
    ('alien_alphabet', 'Write a Python function that derives one valid character order from lexicographically sorted words in an unknown alphabet, raising ValueError for contradictory prefixes or cycles.', 'def derive_alien_alphabet(words):\n    graph = {character: set() for word in words for character in word}\n    indegree = {character: 0 for character in graph}\n    for first, second in zip(words, words[1:]):\n        if len(first) > len(second) and first.startswith(second):\n            raise ValueError("contradictory prefix order")\n        for left, right in zip(first, second):\n            if left != right:\n                if right not in graph[left]:\n                    graph[left].add(right)\n                    indegree[right] += 1\n                break\n    ready = sorted(character for character, degree in indegree.items() if degree == 0)\n    result = []\n    while ready:\n        character = ready.pop(0)\n        result.append(character)\n        for neighbor in sorted(graph[character]):\n            indegree[neighbor] -= 1\n            if indegree[neighbor] == 0:\n                ready.append(neighbor)\n                ready.sort()\n    if len(result) != len(indegree):\n        raise ValueError("alphabet constraints contain a cycle")\n    return "".join(result)'),
    ('dependency_semesters', 'Write a Python function that groups tasks into the minimum prerequisite-respecting semester layers from a task-to-prerequisites dictionary, raising ValueError for cycles.', 'def prerequisite_semesters(prerequisites):\n    tasks = set(prerequisites)\n    for required in prerequisites.values():\n        tasks.update(required)\n    remaining = {task: set(prerequisites.get(task, [])) for task in tasks}\n    semesters = []\n    completed = set()\n    while len(completed) < len(tasks):\n        ready = sorted(task for task in tasks - completed if remaining[task] <= completed)\n        if not ready:\n            raise ValueError("prerequisites contain a cycle")\n        semesters.append(ready)\n        completed.update(ready)\n    return semesters'),
    ('huffman_codes', 'Write a Python function that returns binary prefix codes for symbols with positive frequencies by repeatedly combining the two lightest trees, resolving ties by input order.', 'def huffman_codes(frequencies):\n    if not frequencies:\n        return {}\n    queue = []\n    order = 0\n    for symbol, frequency in frequencies.items():\n        if frequency <= 0:\n            raise ValueError("frequencies must be positive")\n        queue.append((frequency, order, symbol))\n        order += 1\n    while len(queue) > 1:\n        queue.sort(reverse=True)\n        first = queue.pop()\n        second = queue.pop()\n        queue.append((first[0] + second[0], order, (first[2], second[2])))\n        order += 1\n    codes = {}\n    stack = [(queue[0][2], "")]\n    while stack:\n        node, prefix = stack.pop()\n        if isinstance(node, tuple):\n            stack.append((node[1], prefix + "1"))\n            stack.append((node[0], prefix + "0"))\n        else:\n            codes[node] = prefix or "0"\n    return codes'),
    ('gaussian_elimination', 'Write a Python function that solves a nonsingular square linear system using Gaussian elimination with partial pivoting on copied coefficient rows and values.', 'def solve_linear_system(coefficients, values):\n    size = len(coefficients)\n    if len(values) != size or any(len(row) != size for row in coefficients):\n        raise ValueError("system must be square")\n    matrix = [list(row) + [values[index]] for index, row in enumerate(coefficients)]\n    for column in range(size):\n        pivot = max(range(column, size), key=lambda row: abs(matrix[row][column]))\n        if matrix[pivot][column] == 0:\n            raise ValueError("singular system")\n        matrix[column], matrix[pivot] = matrix[pivot], matrix[column]\n        divisor = matrix[column][column]\n        matrix[column] = [value / divisor for value in matrix[column]]\n        for row in range(size):\n            if row == column:\n                continue\n            factor = matrix[row][column]\n            matrix[row] = [left - factor * right for left, right in zip(matrix[row], matrix[column])]\n    return [matrix[row][-1] for row in range(size)]'),
    ('matrix_determinant', 'Write a Python function that computes the determinant of a square numeric matrix by elimination with row swaps without mutating the matrix.', 'def matrix_determinant(matrix):\n    size = len(matrix)\n    if any(len(row) != size for row in matrix):\n        raise ValueError("matrix must be square")\n    work = [list(row) for row in matrix]\n    determinant = 1\n    for column in range(size):\n        pivot = max(range(column, size), key=lambda row: abs(work[row][column]))\n        if work[pivot][column] == 0:\n            return 0\n        if pivot != column:\n            work[column], work[pivot] = work[pivot], work[column]\n            determinant = -determinant\n        pivot_value = work[column][column]\n        determinant *= pivot_value\n        for row in range(column + 1, size):\n            factor = work[row][column] / pivot_value\n            for inner in range(column + 1, size):\n                work[row][inner] -= factor * work[column][inner]\n    return determinant'),
    ('discrete_convolution', 'Write a Python function that returns the full discrete convolution of two numeric sequences using direct multiplication and returns an empty list when either input is empty.', 'def discrete_convolution(first, second):\n    if not first or not second:\n        return []\n    result = [0] * (len(first) + len(second) - 1)\n    for left_index, left_value in enumerate(first):\n        for right_index, right_value in enumerate(second):\n            result[left_index + right_index] += left_value * right_value\n    return result'),
    ('convex_hull', 'Write a Python function that returns the vertices of the convex hull of distinct two-dimensional points in counterclockwise order using the monotone-chain algorithm.', 'def convex_hull(points):\n    ordered = sorted(set(points))\n    if len(ordered) <= 1:\n        return ordered\n    def cross(origin, first, second):\n        return (first[0] - origin[0]) * (second[1] - origin[1]) - (first[1] - origin[1]) * (second[0] - origin[0])\n    lower = []\n    for point in ordered:\n        while len(lower) >= 2 and cross(lower[-2], lower[-1], point) <= 0:\n            lower.pop()\n        lower.append(point)\n    upper = []\n    for point in reversed(ordered):\n        while len(upper) >= 2 and cross(upper[-2], upper[-1], point) <= 0:\n            upper.pop()\n        upper.append(point)\n    return lower[:-1] + upper[:-1]'),
    ('union_find_queries', 'Write a Python function that processes union and connectivity-query operations over numbered elements using disjoint sets with path compression and union by size.', 'def process_connectivity_queries(size, operations):\n    if size < 0:\n        raise ValueError("size must be nonnegative")\n    parent = list(range(size))\n    component_size = [1] * size\n    def find(node):\n        while parent[node] != node:\n            parent[node] = parent[parent[node]]\n            node = parent[node]\n        return node\n    answers = []\n    for operation, left, right in operations:\n        if not (0 <= left < size and 0 <= right < size):\n            raise ValueError("element out of range")\n        left_root, right_root = find(left), find(right)\n        if operation == "union":\n            if left_root != right_root:\n                if component_size[left_root] < component_size[right_root]:\n                    left_root, right_root = right_root, left_root\n                parent[right_root] = left_root\n                component_size[left_root] += component_size[right_root]\n        elif operation == "connected":\n            answers.append(left_root == right_root)\n        else:\n            raise ValueError("unknown operation")\n    return answers'),
    ('lowest_common_ancestors', 'Write a Python function that answers lowest-common-ancestor queries in a rooted tree using binary lifting and rejects nodes not reachable from the root.', 'def lowest_common_ancestors(graph, root, queries):\n    parent = {root: root}\n    depth = {root: 0}\n    queue = [root]\n    for node in queue:\n        for child in graph.get(node, []):\n            if child not in parent:\n                parent[child] = node\n                depth[child] = depth[node] + 1\n                queue.append(child)\n    levels = max(1, len(parent).bit_length())\n    jump = [parent]\n    for _ in range(1, levels):\n        previous = jump[-1]\n        jump.append({node: previous[previous[node]] for node in parent})\n    answers = []\n    for left, right in queries:\n        if left not in parent or right not in parent:\n            raise ValueError("query node is outside the rooted tree")\n        if depth[left] < depth[right]:\n            left, right = right, left\n        difference = depth[left] - depth[right]\n        for bit in range(levels):\n            if difference & (1 << bit):\n                left = jump[bit][left]\n        if left == right:\n            answers.append(left)\n            continue\n        for bit in range(levels - 1, -1, -1):\n            if jump[bit][left] != jump[bit][right]:\n                left, right = jump[bit][left], jump[bit][right]\n        answers.append(parent[left])\n    return answers'),
    ('binary_tree_serialization', 'Write a Python function that round-trips a binary tree represented by nested three-item tuples through a preorder token stream with explicit null markers.', 'def round_trip_binary_tree(tree):\n    tokens = []\n    def encode(node):\n        if node is None:\n            tokens.append(None)\n            return\n        if not isinstance(node, tuple) or len(node) != 3:\n            raise ValueError("nodes must be (value, left, right) tuples")\n        tokens.append(node[0])\n        encode(node[1])\n        encode(node[2])\n    encode(tree)\n    position = 0\n    def decode():\n        nonlocal position\n        if position >= len(tokens):\n            raise ValueError("truncated token stream")\n        value = tokens[position]\n        position += 1\n        if value is None:\n            return None\n        return (value, decode(), decode())\n    restored = decode()\n    if position != len(tokens):\n        raise ValueError("unused tokens")\n    return tokens, restored'),
    ('k_way_merge', 'Write a Python function that merges any number of sorted sequences into one sorted list using a manually maintained minimum heap and stable source ordering.', 'def merge_many_sorted(sequences):\n    heap = []\n    result = []\n    def push(item):\n        heap.append(item)\n        index = len(heap) - 1\n        while index:\n            parent = (index - 1) // 2\n            if heap[parent] <= heap[index]:\n                break\n            heap[parent], heap[index] = heap[index], heap[parent]\n            index = parent\n    for source, sequence in enumerate(sequences):\n        if sequence:\n            push((sequence[0], source, 0))\n    while heap:\n        value, source, offset = heap[0]\n        result.append(value)\n        replacement_offset = offset + 1\n        if replacement_offset < len(sequences[source]):\n            heap[0] = (sequences[source][replacement_offset], source, replacement_offset)\n        else:\n            heap[0] = heap[-1]\n            heap.pop()\n        index = 0\n        while index * 2 + 1 < len(heap):\n            child = index * 2 + 1\n            if child + 1 < len(heap) and heap[child + 1] < heap[child]:\n                child += 1\n            if heap[index] <= heap[child]:\n                break\n            heap[index], heap[child] = heap[child], heap[index]\n            index = child\n    return result'),
    ('aho_corasick_matches', 'Write a Python function that returns all pattern occurrences in text using an Aho-Corasick trie with failure links, including overlapping matches.', 'def multi_pattern_match_indices(text, patterns):\n    transitions = [{}]\n    failure = [0]\n    outputs = [[]]\n    for pattern_index, pattern in enumerate(patterns):\n        if not pattern:\n            raise ValueError("patterns must be non-empty")\n        state = 0\n        for character in pattern:\n            if character not in transitions[state]:\n                transitions[state][character] = len(transitions)\n                transitions.append({})\n                failure.append(0)\n                outputs.append([])\n            state = transitions[state][character]\n        outputs[state].append(pattern_index)\n    queue = list(transitions[0].values())\n    for state in queue:\n        for character, target in transitions[state].items():\n            fallback = failure[state]\n            while fallback and character not in transitions[fallback]:\n                fallback = failure[fallback]\n            failure[target] = transitions[fallback].get(character, 0)\n            outputs[target].extend(outputs[failure[target]])\n            queue.append(target)\n    matches = []\n    state = 0\n    for end, character in enumerate(text):\n        while state and character not in transitions[state]:\n            state = failure[state]\n        state = transitions[state].get(character, 0)\n        for pattern_index in outputs[state]:\n            matches.append((pattern_index, end - len(patterns[pattern_index]) + 1))\n    return matches'),
    ('modular_power', 'Write a Python function that computes a nonnegative integer exponent modulo a positive modulus using repeated squaring.', 'def modular_power(base, exponent, modulus):\n    if exponent < 0 or modulus <= 0:\n        raise ValueError("exponent must be nonnegative and modulus positive")\n    result = 1 % modulus\n    base %= modulus\n    while exponent:\n        if exponent & 1:\n            result = result * base % modulus\n        base = base * base % modulus\n        exponent //= 2\n    return result'),
    ('extended_gcd', 'Write a Python function that returns the greatest common divisor of two integers and Bezout coefficients using the iterative extended Euclidean algorithm.', 'def extended_greatest_common_divisor(left, right):\n    old_remainder, remainder = abs(left), abs(right)\n    old_left, current_left = 1, 0\n    old_right, current_right = 0, 1\n    while remainder:\n        quotient = old_remainder // remainder\n        old_remainder, remainder = remainder, old_remainder - quotient * remainder\n        old_left, current_left = current_left, old_left - quotient * current_left\n        old_right, current_right = current_right, old_right - quotient * current_right\n    return old_remainder, old_left if left >= 0 else -old_left, old_right if right >= 0 else -old_right'),
    ('chinese_remainder', 'Write a Python function that solves pairwise-coprime congruences using constructive inverses and returns the least nonnegative solution with the combined modulus.', 'def solve_coprime_congruences(remainders, moduli):\n    if len(remainders) != len(moduli) or not moduli:\n        raise ValueError("remainders and moduli must be non-empty and aligned")\n    combined = 1\n    for modulus in moduli:\n        if modulus <= 0:\n            raise ValueError("moduli must be positive")\n        combined *= modulus\n    result = 0\n    for remainder, modulus in zip(remainders, moduli):\n        partial = combined // modulus\n        old_remainder, current_remainder = partial, modulus\n        old_coefficient, current_coefficient = 1, 0\n        while current_remainder:\n            quotient = old_remainder // current_remainder\n            old_remainder, current_remainder = current_remainder, old_remainder - quotient * current_remainder\n            old_coefficient, current_coefficient = current_coefficient, old_coefficient - quotient * current_coefficient\n        if old_remainder != 1:\n            raise ValueError("moduli must be pairwise coprime")\n        result += remainder * old_coefficient * partial\n    return result % combined, combined'),
    ('pascal_triangle_row', "Write a Python function that returns a requested zero-indexed row of Pascal's triangle by updating coefficients multiplicatively with exact integer division.", 'def pascal_triangle_row(index):\n    if index < 0:\n        raise ValueError("index must be nonnegative")\n    row = [1]\n    value = 1\n    for column in range(1, index + 1):\n        value = value * (index - column + 1) // column\n        row.append(value)\n    return row'),
    ('gray_code_sequence', 'Write a Python function that returns the reflected binary Gray-code sequence for a nonnegative bit width as fixed-width strings.', 'def reflected_gray_codes(width):\n    if width < 0:\n        raise ValueError("width must be nonnegative")\n    if width == 0:\n        return [""]\n    return [format(value ^ (value >> 1), f"0{width}b") for value in range(1 << width)]'),
    ('next_permutation', 'Write a Python function that returns the next lexicographic permutation of a sequence as a new list, or None when the input is already last.', 'def next_lexicographic_permutation(values):\n    result = list(values)\n    pivot = len(result) - 2\n    while pivot >= 0 and result[pivot] >= result[pivot + 1]:\n        pivot -= 1\n    if pivot < 0:\n        return None\n    successor = len(result) - 1\n    while result[successor] <= result[pivot]:\n        successor -= 1\n    result[pivot], result[successor] = result[successor], result[pivot]\n    result[pivot + 1:] = reversed(result[pivot + 1:])\n    return result'),
    ('josephus_survivor', 'Write a Python function that returns the zero-based surviving position in the Josephus elimination process for positive population and step sizes.', 'def josephus_surviving_position(population, step):\n    if population <= 0 or step <= 0:\n        raise ValueError("population and step must be positive")\n    survivor = 0\n    for size in range(2, population + 1):\n        survivor = (survivor + step) % size\n    return survivor'),
    ('n_queens_solutions', 'Write a Python function that returns every placement of nonattacking queens on an n-by-n board as tuples of column indices, ordered by row.', 'def solve_n_queens(size):\n    if size < 0:\n        raise ValueError("size must be nonnegative")\n    solutions = []\n    columns = set()\n    rising = set()\n    falling = set()\n    placement = []\n    def place(row):\n        if row == size:\n            solutions.append(tuple(placement))\n            return\n        for column in range(size):\n            if column in columns or row + column in rising or row - column in falling:\n                continue\n            columns.add(column)\n            rising.add(row + column)\n            falling.add(row - column)\n            placement.append(column)\n            place(row + 1)\n            placement.pop()\n            falling.remove(row - column)\n            rising.remove(row + column)\n            columns.remove(column)\n    place(0)\n    return solutions'),
    ('sudoku_solver', 'Write a Python function that solves a nine-by-nine Sudoku grid containing zeroes for blanks by backtracking with row, column, and box constraints, without mutating the input.', 'def solve_sudoku(grid):\n    if len(grid) != 9 or any(len(row) != 9 for row in grid):\n        raise ValueError("grid must be nine by nine")\n    board = [list(row) for row in grid]\n    rows = [set() for _ in range(9)]\n    columns = [set() for _ in range(9)]\n    boxes = [set() for _ in range(9)]\n    blanks = []\n    for row in range(9):\n        for column in range(9):\n            value = board[row][column]\n            if value == 0:\n                blanks.append((row, column))\n                continue\n            box = row // 3 * 3 + column // 3\n            if value not in range(1, 10) or value in rows[row] or value in columns[column] or value in boxes[box]:\n                raise ValueError("invalid grid")\n            rows[row].add(value)\n            columns[column].add(value)\n            boxes[box].add(value)\n    def fill(position):\n        if position == len(blanks):\n            return True\n        best = min(range(position, len(blanks)), key=lambda index: len(set(range(1, 10)) - rows[blanks[index][0]] - columns[blanks[index][1]] - boxes[blanks[index][0] // 3 * 3 + blanks[index][1] // 3]))\n        blanks[position], blanks[best] = blanks[best], blanks[position]\n        row, column = blanks[position]\n        box = row // 3 * 3 + column // 3\n        for value in sorted(set(range(1, 10)) - rows[row] - columns[column] - boxes[box]):\n            board[row][column] = value\n            rows[row].add(value); columns[column].add(value); boxes[box].add(value)\n            if fill(position + 1):\n                return True\n            rows[row].remove(value); columns[column].remove(value); boxes[box].remove(value)\n        board[row][column] = 0\n        blanks[position], blanks[best] = blanks[best], blanks[position]\n        return False\n    if not fill(0):\n        return None\n    return board'),
    ('stable_matching', 'Write a Python function that computes a stable one-to-one matching from two complete preference dictionaries using proposer-optimal deferred acceptance.', 'def stable_preference_matching(proposer_preferences, receiver_preferences):\n    proposers = set(proposer_preferences)\n    receivers = set(receiver_preferences)\n    if any(set(order) != receivers for order in proposer_preferences.values()) or any(set(order) != proposers for order in receiver_preferences.values()):\n        raise ValueError("preferences must be complete")\n    ranks = {receiver: {proposer: rank for rank, proposer in enumerate(order)} for receiver, order in receiver_preferences.items()}\n    next_choice = {proposer: 0 for proposer in proposers}\n    free = list(proposers)\n    held = {}\n    while free:\n        proposer = free.pop()\n        order = proposer_preferences[proposer]\n        if next_choice[proposer] == len(order):\n            raise ValueError("no complete matching exists")\n        receiver = order[next_choice[proposer]]\n        next_choice[proposer] += 1\n        current = held.get(receiver)\n        if current is None or ranks[receiver][proposer] < ranks[receiver][current]:\n            held[receiver] = proposer\n            if current is not None:\n                free.append(current)\n        else:\n            free.append(proposer)\n    return {proposer: receiver for receiver, proposer in held.items()}'),
    ('bipartite_maximum_matching', 'Write a Python function that returns a maximum matching from left-side nodes to right-side nodes in a bipartite adjacency dictionary using augmenting paths.', 'def maximum_bipartite_matching(graph):\n    right_match = {}\n    def augment(left, seen):\n        for right in graph.get(left, []):\n            if right in seen:\n                continue\n            seen.add(right)\n            if right not in right_match or augment(right_match[right], seen):\n                right_match[right] = left\n                return True\n        return False\n    for left in graph:\n        augment(left, set())\n    return {left: right for right, left in right_match.items()}'),
    ('interval_stabbing_points', 'Write a Python function that returns a minimum-size sorted set of points intersecting every closed interval by greedily selecting right endpoints.', 'def minimum_interval_stabbing_points(intervals):\n    ordered = []\n    for start, end in intervals:\n        if start > end:\n            raise ValueError("interval start exceeds end")\n        ordered.append((end, start))\n    points = []\n    for end, start in sorted(ordered):\n        if not points or points[-1] < start:\n            points.append(end)\n    return points'),
    ('graph_k_core', 'Write a Python function that returns the vertices in the k-core of an undirected adjacency dictionary by repeatedly removing vertices below the degree threshold.', 'def graph_k_core_vertices(graph, threshold):\n    if threshold < 0:\n        raise ValueError("threshold must be nonnegative")\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    neighbors = {node: set(graph.get(node, [])) & nodes for node in nodes}\n    active = set(nodes)\n    queue = [node for node in active if len(neighbors[node]) < threshold]\n    position = 0\n    while position < len(queue):\n        node = queue[position]\n        position += 1\n        if node not in active:\n            continue\n        active.remove(node)\n        for neighbor in neighbors[node] & active:\n            neighbors[neighbor].discard(node)\n            if len(neighbors[neighbor] & active) < threshold:\n                queue.append(neighbor)\n    return active'),
    ('page_rank', 'Write a Python function that computes a fixed number of PageRank iterations for a directed adjacency dictionary, redistributing dangling-node mass uniformly.', 'def iterative_page_rank(graph, iterations, damping=0.85):\n    if iterations < 0 or not 0 <= damping <= 1:\n        raise ValueError("invalid iteration count or damping")\n    nodes = set(graph)\n    for targets in graph.values():\n        nodes.update(targets)\n    if not nodes:\n        return {}\n    count = len(nodes)\n    rank = {node: 1 / count for node in nodes}\n    for _ in range(iterations):\n        dangling = sum(rank[node] for node in nodes if not graph.get(node))\n        updated = {node: (1 - damping) / count + damping * dangling / count for node in nodes}\n        for source in nodes:\n            targets = graph.get(source, [])\n            if targets:\n                share = damping * rank[source] / len(targets)\n                for target in targets:\n                    updated[target] += share\n        rank = updated\n    return rank'),
    ('game_of_life_step', "Write a Python function that computes one Conway's Game of Life step for a rectangular zero-one grid without mutating it.", 'def game_of_life_step(grid):\n    if not grid:\n        return []\n    columns = len(grid[0])\n    if any(len(row) != columns for row in grid) or any(value not in (0, 1) for row in grid for value in row):\n        raise ValueError("grid must be rectangular and binary")\n    result = [[0] * columns for _ in grid]\n    for row in range(len(grid)):\n        for column in range(columns):\n            neighbors = 0\n            for row_delta in (-1, 0, 1):\n                for column_delta in (-1, 0, 1):\n                    if row_delta == column_delta == 0:\n                        continue\n                    next_row, next_column = row + row_delta, column + column_delta\n                    if 0 <= next_row < len(grid) and 0 <= next_column < columns:\n                        neighbors += grid[next_row][next_column]\n            result[row][column] = int(neighbors == 3 or grid[row][column] == 1 and neighbors == 2)\n    return result'),
    ('takeaway_game_strategy', 'Write a Python function that determines whether the first player can force a win in a finite subtraction game and returns one winning opening move when available.', 'def subtraction_game_opening(total, moves):\n    if total < 0 or not moves or any(move <= 0 for move in moves):\n        raise ValueError("total must be nonnegative and moves positive")\n    allowed = sorted(set(moves))\n    winning = [False] * (total + 1)\n    choice = [None] * (total + 1)\n    for stones in range(1, total + 1):\n        for move in allowed:\n            if move > stones:\n                break\n            if not winning[stones - move]:\n                winning[stones] = True\n                choice[stones] = move\n                break\n    return winning[total], choice[total]'),
    ('polynomial_division', 'Write a Python function that divides one polynomial by another using descending-power coefficient lists and returns quotient and remainder without mutating either input.', 'def divide_polynomials(dividend, divisor):\n    if not divisor or all(coefficient == 0 for coefficient in divisor):\n        raise ValueError("divisor must be nonzero")\n    numerator = list(dividend)\n    while numerator and numerator[0] == 0:\n        numerator.pop(0)\n    denominator = list(divisor)\n    while denominator and denominator[0] == 0:\n        denominator.pop(0)\n    if len(numerator) < len(denominator):\n        return [0], numerator or [0]\n    quotient = [0] * (len(numerator) - len(denominator) + 1)\n    for offset in range(len(quotient)):\n        factor = numerator[offset] / denominator[0]\n        quotient[offset] = factor\n        for index, coefficient in enumerate(denominator):\n            numerator[offset + index] -= factor * coefficient\n    remainder = numerator[len(quotient):]\n    while len(remainder) > 1 and remainder[0] == 0:\n        remainder.pop(0)\n    return quotient, remainder or [0]'),
    ('trapezoidal_integral', 'Write a Python function that estimates the integral of tabulated values at strictly increasing coordinates using the composite trapezoidal rule.', 'def trapezoidal_integral(coordinates, values):\n    if len(coordinates) != len(values) or len(coordinates) < 2:\n        raise ValueError("coordinates and values must align and contain at least two points")\n    total = 0\n    for index in range(1, len(coordinates)):\n        width = coordinates[index] - coordinates[index - 1]\n        if width <= 0:\n            raise ValueError("coordinates must be strictly increasing")\n        total += width * (values[index - 1] + values[index]) / 2\n    return total'),
    ('tridiagonal_system', 'Write a Python function that solves a nonsingular tridiagonal linear system from its three diagonals using the Thomas algorithm on copied values.', 'def solve_tridiagonal_system(lower, diagonal, upper, values):\n    size = len(diagonal)\n    if len(values) != size or len(lower) != max(0, size - 1) or len(upper) != max(0, size - 1):\n        raise ValueError("diagonal lengths do not align")\n    if size == 0:\n        return []\n    pivots = list(diagonal)\n    result = list(values)\n    for index in range(1, size):\n        if pivots[index - 1] == 0:\n            raise ValueError("zero pivot")\n        factor = lower[index - 1] / pivots[index - 1]\n        pivots[index] -= factor * upper[index - 1]\n        result[index] -= factor * result[index - 1]\n    if pivots[-1] == 0:\n        raise ValueError("zero pivot")\n    solution = [0] * size\n    solution[-1] = result[-1] / pivots[-1]\n    for index in range(size - 2, -1, -1):\n        if pivots[index] == 0:\n            raise ValueError("zero pivot")\n        solution[index] = (result[index] - upper[index] * solution[index + 1]) / pivots[index]\n    return solution'),
    ('lazy_segment_range_sums', 'Write a Python function that processes inclusive range-add and range-sum operations using a lazy-propagation segment tree without mutating the initial sequence.', 'def process_range_add_sum(values, operations):\n    size = len(values)\n    tree = [0] * max(1, size * 4)\n    lazy = [0] * max(1, size * 4)\n    def build(node, left, right):\n        if left == right:\n            tree[node] = values[left]\n            return\n        middle = (left + right) // 2\n        build(node * 2, left, middle)\n        build(node * 2 + 1, middle + 1, right)\n        tree[node] = tree[node * 2] + tree[node * 2 + 1]\n    def push(node, left, right):\n        if lazy[node] and left != right:\n            middle = (left + right) // 2\n            for child, width in ((node * 2, middle - left + 1), (node * 2 + 1, right - middle)):\n                tree[child] += lazy[node] * width\n                lazy[child] += lazy[node]\n        lazy[node] = 0\n    def update(node, left, right, start, end, amount):\n        if start <= left and right <= end:\n            tree[node] += amount * (right - left + 1)\n            lazy[node] += amount\n            return\n        push(node, left, right)\n        middle = (left + right) // 2\n        if start <= middle:\n            update(node * 2, left, middle, start, end, amount)\n        if end > middle:\n            update(node * 2 + 1, middle + 1, right, start, end, amount)\n        tree[node] = tree[node * 2] + tree[node * 2 + 1]\n    def query(node, left, right, start, end):\n        if start <= left and right <= end:\n            return tree[node]\n        push(node, left, right)\n        middle = (left + right) // 2\n        total = 0\n        if start <= middle:\n            total += query(node * 2, left, middle, start, end)\n        if end > middle:\n            total += query(node * 2 + 1, middle + 1, right, start, end)\n        return total\n    if size:\n        build(1, 0, size - 1)\n    answers = []\n    for operation in operations:\n        if size == 0 or not 0 <= operation[1] <= operation[2] < size:\n            raise ValueError("invalid range")\n        if operation[0] == "add":\n            update(1, 0, size - 1, operation[1], operation[2], operation[3])\n        elif operation[0] == "sum":\n            answers.append(query(1, 0, size - 1, operation[1], operation[2]))\n        else:\n            raise ValueError("unknown operation")\n    return answers'),
    ('centered_interval_queries', 'Write a Python function that builds a centered interval index and returns all closed intervals containing each query point.', 'def intervals_containing_points(intervals, points):\n    checked = []\n    for start, end in intervals:\n        if start > end:\n            raise ValueError("interval start exceeds end")\n        checked.append((start, end))\n    def build(items):\n        if not items:\n            return None\n        endpoints = sorted(value for interval in items for value in interval)\n        center = endpoints[len(endpoints) // 2]\n        left, crossing, right = [], [], []\n        for interval in items:\n            if interval[1] < center:\n                left.append(interval)\n            elif interval[0] > center:\n                right.append(interval)\n            else:\n                crossing.append(interval)\n        return (center, crossing, build(left), build(right))\n    root = build(checked)\n    def search(node, point, result):\n        if node is None:\n            return\n        center, crossing, left, right = node\n        result.extend(interval for interval in crossing if interval[0] <= point <= interval[1])\n        search(left if point < center else right, point, result)\n    answers = []\n    for point in points:\n        matches = []\n        search(root, point, matches)\n        answers.append(sorted(matches))\n    return answers'),
    ('kd_tree_nearest', 'Write a Python function that returns the nearest point to each query in two dimensions by constructing and pruning a balanced k-d tree.', 'def kd_tree_nearest_points(points, queries):\n    if not points:\n        raise ValueError("points must be non-empty")\n    if any(len(point) != 2 for point in points) or any(len(query) != 2 for query in queries):\n        raise ValueError("points must be two-dimensional")\n    def build(items, depth=0):\n        if not items:\n            return None\n        axis = depth % 2\n        ordered = sorted(items, key=lambda point: (point[axis], point[1 - axis]))\n        middle = len(ordered) // 2\n        return (ordered[middle], axis, build(ordered[:middle], depth + 1), build(ordered[middle + 1:], depth + 1))\n    root = build(list(points))\n    def nearest(node, query, best):\n        if node is None:\n            return best\n        point, axis, left, right = node\n        distance = (point[0] - query[0]) ** 2 + (point[1] - query[1]) ** 2\n        if best is None or (distance, point) < best:\n            best = (distance, point)\n        difference = query[axis] - point[axis]\n        near, far = (left, right) if difference < 0 else (right, left)\n        best = nearest(near, query, best)\n        if difference * difference <= best[0]:\n            best = nearest(far, query, best)\n        return best\n    return [nearest(root, query, None)[1] for query in queries]'),
    ('quadtree_encoding', 'Write a Python function that encodes a non-empty square binary grid whose side is a power of two as a recursively nested quadtree, collapsing uniform regions.', 'def encode_binary_quadtree(grid):\n    size = len(grid)\n    if size == 0 or size & (size - 1) or any(len(row) != size for row in grid) or any(value not in (0, 1) for row in grid for value in row):\n        raise ValueError("grid must be square, binary, and power-of-two sized")\n    def encode(top, left, width):\n        first = grid[top][left]\n        if all(grid[row][column] == first for row in range(top, top + width) for column in range(left, left + width)):\n            return first\n        half = width // 2\n        return (encode(top, left, half), encode(top, left + half, half), encode(top + half, left, half), encode(top + half, left + half, half))\n    return encode(0, 0, size)'),
    ('burrows_wheeler_transform', 'Write a Python function that computes the Burrows-Wheeler transform of a string and the original row index without requiring a sentinel character.', 'def burrows_wheeler_transform(text):\n    if not text:\n        return "", 0\n    rotations = sorted((text[index:] + text[:index], index) for index in range(len(text)))\n    transformed = "".join(rotation[-1] for rotation, _ in rotations)\n    original_index = next(position for position, (_, start) in enumerate(rotations) if start == 0)\n    return transformed, original_index'),
    ('lzw_compression', 'Write a Python function that compresses a sequence of byte values into integer codes using Lempel-Ziv-Welch dictionary growth.', 'def lzw_compress_bytes(values):\n    if any(not isinstance(value, int) or not 0 <= value <= 255 for value in values):\n        raise ValueError("values must be bytes")\n    dictionary = {(value,): value for value in range(256)}\n    next_code = 256\n    current = ()\n    output = []\n    for value in values:\n        candidate = current + (value,)\n        if candidate in dictionary:\n            current = candidate\n        else:\n            output.append(dictionary[current])\n            dictionary[candidate] = next_code\n            next_code += 1\n            current = (value,)\n    if current:\n        output.append(dictionary[current])\n    return output'),
    ('crc32_checksum', 'Write a Python function that computes the standard reflected CRC-32 checksum of byte values using the polynomial 0xEDB88320.', 'def crc32_checksum(values):\n    checksum = 0xFFFFFFFF\n    for value in values:\n        if not isinstance(value, int) or not 0 <= value <= 255:\n            raise ValueError("values must be bytes")\n        checksum ^= value\n        for _ in range(8):\n            checksum = (checksum >> 1) ^ (0xEDB88320 if checksum & 1 else 0)\n    return checksum ^ 0xFFFFFFFF'),
    ('unsigned_varint_round_trip', 'Write a Python function that encodes nonnegative integers as base-128 varints and decodes the resulting byte stream back to the original values.', 'def round_trip_unsigned_varints(values):\n    encoded = []\n    for value in values:\n        if not isinstance(value, int) or value < 0:\n            raise ValueError("values must be nonnegative integers")\n        remaining = value\n        while remaining >= 128:\n            encoded.append((remaining & 127) | 128)\n            remaining >>= 7\n        encoded.append(remaining)\n    decoded = []\n    value = shift = 0\n    for byte in encoded:\n        value |= (byte & 127) << shift\n        if byte & 128:\n            shift += 7\n        else:\n            decoded.append(value)\n            value = shift = 0\n    if shift:\n        raise ValueError("truncated varint")\n    return encoded, decoded'),
    ('json_pointer_lookup', 'Write a Python function that resolves RFC 6901-style JSON Pointer paths through nested dictionaries and lists, including escaped slash and tilde tokens.', 'def resolve_json_pointer(document, pointer):\n    if pointer == "":\n        return document\n    if not pointer.startswith("/"):\n        raise ValueError("pointer must be empty or begin with a slash")\n    current = document\n    for raw_token in pointer[1:].split("/"):\n        token = raw_token.replace("~1", "/").replace("~0", "~")\n        if isinstance(current, dict):\n            current = current[token]\n        elif isinstance(current, list):\n            if token == "-" or not token.isdigit():\n                raise ValueError("invalid list index")\n            current = current[int(token)]\n        else:\n            raise ValueError("pointer continues through a scalar")\n    return current'),
    ('deep_mapping_merge', 'Write a Python function that recursively merges two nested dictionaries into a new structure, replacing non-dictionary conflicts with right-side values.', 'def deep_merge_mappings(left, right):\n    def copy_value(value):\n        if isinstance(value, dict):\n            return {key: copy_value(item) for key, item in value.items()}\n        if isinstance(value, list):\n            return [copy_value(item) for item in value]\n        return value\n    result = {key: copy_value(value) for key, value in left.items()}\n    for key, value in right.items():\n        if key in result and isinstance(result[key], dict) and isinstance(value, dict):\n            result[key] = deep_merge_mappings(result[key], value)\n        else:\n            result[key] = copy_value(value)\n    return result'),
    ('event_sessionization', 'Write a Python function that groups timestamped events by key into sessions separated by more than a supplied nonnegative inactivity gap.', 'def sessionize_events(events, inactivity_gap):\n    if inactivity_gap < 0:\n        raise ValueError("inactivity gap must be nonnegative")\n    grouped = {}\n    for event in events:\n        grouped.setdefault(event["key"], []).append(dict(event))\n    sessions = []\n    for key, records in grouped.items():\n        records.sort(key=lambda record: record["timestamp"])\n        current = []\n        previous = None\n        for record in records:\n            if previous is not None and record["timestamp"] - previous > inactivity_gap:\n                sessions.append({"key": key, "events": current})\n                current = []\n            current.append(record)\n            previous = record["timestamp"]\n        if current:\n            sessions.append({"key": key, "events": current})\n    sessions.sort(key=lambda session: (session["events"][0]["timestamp"], session["key"]))\n    return sessions'),
    ('asof_join', 'Write a Python function that left-joins timestamped records to the latest same-key reference record at or before each timestamp.', 'def backward_asof_join(records, references):\n    by_key = {}\n    for reference in references:\n        by_key.setdefault(reference["key"], []).append(dict(reference))\n    for values in by_key.values():\n        values.sort(key=lambda record: record["timestamp"])\n    result = []\n    for record in records:\n        candidates = by_key.get(record["key"], [])\n        left, right = 0, len(candidates)\n        while left < right:\n            middle = (left + right) // 2\n            if candidates[middle]["timestamp"] <= record["timestamp"]:\n                left = middle + 1\n            else:\n                right = middle\n        result.append({"record": dict(record), "reference": None if left == 0 else dict(candidates[left - 1])})\n    return result'),
    ('fixed_bucket_resampling', 'Write a Python function that sums timestamped numeric observations into fixed-width half-open buckets and emits empty buckets between the observed endpoints.', 'def resample_fixed_buckets(observations, width):\n    if width <= 0:\n        raise ValueError("width must be positive")\n    if not observations:\n        return []\n    totals = {}\n    for timestamp, value in observations:\n        bucket = timestamp // width * width\n        totals[bucket] = totals.get(bucket, 0) + value\n    start, end = min(totals), max(totals)\n    return [(bucket, totals.get(bucket, 0)) for bucket in range(start, end + width, width)]'),
    ('fifo_page_faults', 'Write a Python function that simulates positive-capacity first-in-first-out page replacement and returns both the fault count and final frame order.', 'def simulate_fifo_page_replacement(references, capacity):\n    if capacity <= 0:\n        raise ValueError("capacity must be positive")\n    frames = []\n    present = set()\n    faults = 0\n    for page in references:\n        if page in present:\n            continue\n        faults += 1\n        if len(frames) == capacity:\n            present.remove(frames.pop(0))\n        frames.append(page)\n        present.add(page)\n    return faults, frames'),
    ('banker_safe_sequence', "Write a Python function that returns one safe process-completion order under Banker's algorithm from allocation, maximum-demand, and available-resource matrices, or None when unsafe.", 'def banker_safe_sequence(allocation, maximum, available):\n    if len(allocation) != len(maximum) or any(len(row) != len(available) for row in allocation + maximum):\n        raise ValueError("resource dimensions do not align")\n    need = []\n    for held, limit in zip(allocation, maximum):\n        row = [limit[index] - held[index] for index in range(len(available))]\n        if any(value < 0 for value in row):\n            raise ValueError("allocation exceeds maximum")\n        need.append(row)\n    work = list(available)\n    unfinished = set(range(len(allocation)))\n    order = []\n    while unfinished:\n        process = next((candidate for candidate in sorted(unfinished) if all(need[candidate][resource] <= work[resource] for resource in range(len(work)))), None)\n        if process is None:\n            return None\n        for resource, amount in enumerate(allocation[process]):\n            work[resource] += amount\n        unfinished.remove(process)\n        order.append(process)\n    return order'),
    ('ordinary_linear_regression', 'Write a Python function that computes slope, intercept, and coefficient of determination for paired numeric observations using ordinary least squares.', 'def simple_linear_regression(inputs, outputs):\n    if len(inputs) != len(outputs) or len(inputs) < 2:\n        raise ValueError("inputs and outputs must align and contain at least two observations")\n    input_mean = sum(inputs) / len(inputs)\n    output_mean = sum(outputs) / len(outputs)\n    input_variation = sum((value - input_mean) ** 2 for value in inputs)\n    if input_variation == 0:\n        raise ValueError("inputs must vary")\n    slope = sum((left - input_mean) * (right - output_mean) for left, right in zip(inputs, outputs)) / input_variation\n    intercept = output_mean - slope * input_mean\n    predictions = [intercept + slope * value for value in inputs]\n    residual = sum((actual - predicted) ** 2 for actual, predicted in zip(outputs, predictions))\n    total = sum((actual - output_mean) ** 2 for actual in outputs)\n    determination = 1.0 if total == 0 and residual == 0 else 0.0 if total == 0 else 1 - residual / total\n    return slope, intercept, determination'),
    ('sample_covariance_matrix', 'Write a Python function that computes a sample covariance matrix from equal-width observation rows, requiring at least two observations.', 'def sample_covariance_matrix(observations):\n    if len(observations) < 2:\n        raise ValueError("at least two observations are required")\n    width = len(observations[0])\n    if any(len(row) != width for row in observations):\n        raise ValueError("observations must have equal width")\n    means = [sum(row[column] for row in observations) / len(observations) for column in range(width)]\n    return [[sum((row[left] - means[left]) * (row[right] - means[right]) for row in observations) / (len(observations) - 1) for right in range(width)] for left in range(width)]'),
    ('kmeans_iterations', 'Write a Python function that runs a fixed number of deterministic k-means iterations from supplied equal-dimensional centroids and returns final assignments and centroids.', 'def run_kmeans_iterations(points, centroids, iterations):\n    if iterations < 0 or not centroids:\n        raise ValueError("iterations must be nonnegative and centroids non-empty")\n    width = len(centroids[0])\n    if any(len(point) != width for point in points) or any(len(center) != width for center in centroids):\n        raise ValueError("dimensions do not align")\n    centers = [list(center) for center in centroids]\n    assignments = []\n    for _ in range(iterations):\n        assignments = [min(range(len(centers)), key=lambda index: (sum((value - centers[index][axis]) ** 2 for axis, value in enumerate(point)), index)) for point in points]\n        groups = [[] for _ in centers]\n        for point, assignment in zip(points, assignments):\n            groups[assignment].append(point)\n        centers = [[sum(point[axis] for point in group) / len(group) for axis in range(width)] if group else centers[index] for index, group in enumerate(groups)]\n    if iterations == 0:\n        assignments = [min(range(len(centers)), key=lambda index: (sum((value - centers[index][axis]) ** 2 for axis, value in enumerate(point)), index)) for point in points]\n    return assignments, centers'),
    ('dbscan_clusters', 'Write a Python function that labels fixed-dimensional points with DBSCAN cluster identifiers or -1 for noise using squared Euclidean distance.', 'def dbscan_cluster_labels(points, radius, minimum_points):\n    if radius < 0 or minimum_points <= 0 or (points and any(len(point) != len(points[0]) for point in points)):\n        raise ValueError("invalid radius, minimum, or dimensions")\n    def neighbors(index):\n        return [candidate for candidate, point in enumerate(points) if sum((left - right) ** 2 for left, right in zip(points[index], point)) <= radius * radius]\n    unvisited = None\n    labels = [unvisited] * len(points)\n    cluster = 0\n    for index in range(len(points)):\n        if labels[index] is not unvisited:\n            continue\n        nearby = neighbors(index)\n        if len(nearby) < minimum_points:\n            labels[index] = -1\n            continue\n        labels[index] = cluster\n        queue = list(nearby)\n        position = 0\n        while position < len(queue):\n            candidate = queue[position]\n            position += 1\n            if labels[candidate] == -1:\n                labels[candidate] = cluster\n            if labels[candidate] is not unvisited:\n                continue\n            labels[candidate] = cluster\n            expanded = neighbors(candidate)\n            if len(expanded) >= minimum_points:\n                queue.extend(item for item in expanded if item not in queue)\n        cluster += 1\n    return labels'),
    ('point_in_polygon', 'Write a Python function that classifies whether each two-dimensional query point lies inside or on the boundary of a simple polygon using ray casting.', 'def points_inside_polygon(polygon, points):\n    if len(polygon) < 3:\n        raise ValueError("polygon needs at least three vertices")\n    answers = []\n    for point_x, point_y in points:\n        inside = False\n        for index, first in enumerate(polygon):\n            second = polygon[(index + 1) % len(polygon)]\n            cross = (second[0] - first[0]) * (point_y - first[1]) - (second[1] - first[1]) * (point_x - first[0])\n            if cross == 0 and min(first[0], second[0]) <= point_x <= max(first[0], second[0]) and min(first[1], second[1]) <= point_y <= max(first[1], second[1]):\n                inside = True\n                break\n            if (first[1] > point_y) != (second[1] > point_y):\n                intersection = first[0] + (point_y - first[1]) * (second[0] - first[0]) / (second[1] - first[1])\n                if point_x < intersection:\n                    inside = not inside\n        answers.append(inside)\n    return answers'),
    ('line_segment_intersection', 'Write a Python function that determines whether each pair of closed two-dimensional line segments intersects, including collinear endpoint overlap.', 'def segment_intersection_flags(segment_pairs):\n    def orientation(first, second, third):\n        value = (second[0] - first[0]) * (third[1] - first[1]) - (second[1] - first[1]) * (third[0] - first[0])\n        return 0 if value == 0 else 1 if value > 0 else -1\n    def on_segment(first, point, second):\n        return min(first[0], second[0]) <= point[0] <= max(first[0], second[0]) and min(first[1], second[1]) <= point[1] <= max(first[1], second[1])\n    result = []\n    for (first, second), (third, fourth) in segment_pairs:\n        values = (orientation(first, second, third), orientation(first, second, fourth), orientation(third, fourth, first), orientation(third, fourth, second))\n        intersects = values[0] != values[1] and values[2] != values[3]\n        intersects = intersects or values[0] == 0 and on_segment(first, third, second)\n        intersects = intersects or values[1] == 0 and on_segment(first, fourth, second)\n        intersects = intersects or values[2] == 0 and on_segment(third, first, fourth)\n        intersects = intersects or values[3] == 0 and on_segment(third, second, fourth)\n        result.append(intersects)\n    return result'),
    ('polygon_area_centroid', 'Write a Python function that returns the signed area and centroid of a nondegenerate simple polygon using cross products.', 'def polygon_area_and_centroid(vertices):\n    if len(vertices) < 3:\n        raise ValueError("polygon needs at least three vertices")\n    doubled_area = 0\n    x_total = y_total = 0\n    for index, first in enumerate(vertices):\n        second = vertices[(index + 1) % len(vertices)]\n        cross = first[0] * second[1] - second[0] * first[1]\n        doubled_area += cross\n        x_total += (first[0] + second[0]) * cross\n        y_total += (first[1] + second[1]) * cross\n    if doubled_area == 0:\n        raise ValueError("polygon must have nonzero area")\n    return doubled_area / 2, (x_total / (3 * doubled_area), y_total / (3 * doubled_area))'),
    ('havel_hakimi_graphical', 'Write a Python function that decides whether a sequence of nonnegative integers is graphical using the Havel-Hakimi reduction.', 'def is_graphical_degree_sequence(degrees):\n    if any(not isinstance(degree, int) or degree < 0 for degree in degrees):\n        raise ValueError("degrees must be nonnegative integers")\n    remaining = list(degrees)\n    while True:\n        remaining = sorted((degree for degree in remaining if degree), reverse=True)\n        if not remaining:\n            return True\n        degree = remaining.pop(0)\n        if degree > len(remaining):\n            return False\n        for index in range(degree):\n            remaining[index] -= 1\n            if remaining[index] < 0:\n                return False'),
    ('prufer_tree_encoding', 'Write a Python function that encodes a labeled undirected tree as its Prüfer sequence, validating that the edges form one tree.', 'def prufer_encode_tree(edges):\n    if not edges:\n        return []\n    nodes = set()\n    adjacency = {}\n    for left, right in edges:\n        if left == right:\n            raise ValueError("self loops are not tree edges")\n        nodes.update((left, right))\n        adjacency.setdefault(left, set()).add(right)\n        adjacency.setdefault(right, set()).add(left)\n    if len(edges) != len(nodes) - 1:\n        raise ValueError("edges do not form a tree")\n    seen = set()\n    queue = [next(iter(nodes))]\n    for node in queue:\n        if node in seen:\n            continue\n        seen.add(node)\n        queue.extend(adjacency[node] - seen)\n    if seen != nodes:\n        raise ValueError("edges do not form a connected tree")\n    sequence = []\n    for _ in range(len(nodes) - 2):\n        leaf = min(node for node in nodes if len(adjacency[node]) == 1)\n        neighbor = next(iter(adjacency[leaf]))\n        sequence.append(neighbor)\n        adjacency[neighbor].remove(leaf)\n        adjacency[leaf].clear()\n    return sequence'),
)
